type SortOption = "relevance" | "date" | "author" | "title"

const HIDDEN_SEARCH_RESULT_TYPES = new Set(["repo", "pr"])
const SEARCH_RESULT_TYPE_MAP: Record<SearchResult["type"], string> = {
  repo: "repos",
  checkpoint: "checkpoints",
  commit: "commits",
  pr: "prs",
  session: "sessions",
}

interface SearchPageParams {
  q?: string
  types?: string
  repo?: string
  author?: string
  date?: string
  branch?: string
  sort?: string
}

export const Route = createFileRoute("/_app/_authenticated/search")({
  beforeLoad: ({ context }) => {
    // Respect dev overrides (VITE_FORCE_FLAG_SEMANTIC_SEARCH, VITE_FORCE_ALL_FLAGS)
    const localOverride = getLocalFeatureFlagOverride("semantic-search")
    if (localOverride !== undefined) {
      if (!localOverride) throw notFound()
      return
    }
    const globalOverride = getGlobalFeatureFlagOverride()
    if (globalOverride !== undefined) {
      if (!globalOverride) throw notFound()
      return
    }
    if (!context.auth.user?.feature_flags?.["semantic-search"]) {
      throw notFound()
    }
  },
  component: SearchPage,
  validateSearch: (search: Record<string, unknown>): SearchPageParams => ({
    q: (search.q as string) || undefined,
    types: (search.types as string) || undefined,
    repo: (search.repo as string) || undefined,
    author: (search.author as string) || undefined,
    date: (search.date as string) || undefined,
    branch: (search.branch as string) || undefined,
    sort: (search.sort as string) || undefined,
  }),
})

function SearchPage() {
  const navigate = useNavigate({ from: "/search" })
  const { types, author } = Route.useSearch()
  const { recent } = useRecentSearches()

  const [urlQuery, setUrlQuery] = useSearchParamState({
    key: "q",
    type: "string",
    defaultValue: "",
  })
  const {
    draftQuery: query,
    setDraftQuery: setQuery,
    committedQuery,
    isStale: isQueryStale,
    setQueryImmediately,
  } = useDeferredQuery(urlQuery, { onCommit: setUrlQuery, delay: 350 })

  const [repo, setRepo] = useSearchParamState({
    key: "repo",
    type: "string",
    defaultValue: "",
  })
  const [date, setDate] = useSearchParamState({
    key: "date",
    type: "string",
    defaultValue: "",
  })
  const [branch, setBranch] = useSearchParamState({
    key: "branch",
    type: "string",
    defaultValue: "",
  })
  const [sortParam, setSortParam] = useSearchParamState({
    key: "sort",
    type: "string",
    defaultValue: "relevance",
  })

  const trimmedQuery = query.trim()
  const hasQuery = trimmedQuery.length > 0

  const posthog = usePostHog()

  // Pass the explicitly-selected type tab to the API as `filterType` so the
  // server filters results by type before pagination. Counts are always computed
  // from the full (unfiltered) result set, so tab counts stay accurate.
  const validFilterTypes = ["checkpoints", "commits", "sessions"] as const
  const filterType = validFilterTypes.includes(types as any)
    ? (types as "checkpoints" | "commits" | "sessions")
    : undefined
  const { data, isFetching, isPending, isPlaceholderData, isError } = useGlobalSearchQuery(
    committedQuery.trim().length > 0
      ? {
          q: committedQuery.trim(),
          limit: 100,
          repo: repo || undefined,
          branch: branch || undefined,
          author: author || undefined,
          date: (date as "week" | "month") || undefined,
          ...(filterType ? { filterType } : {}),
        }
      : null,
    { source: "search_page" },
  )

  const allResults = useMemo(() => data?.results ?? [], [data?.results])
  const visibleResults = useMemo(
    () => allResults.filter((result) => !HIDDEN_SEARCH_RESULT_TYPES.has(result.type)),
    [allResults],
  )

  const hasActiveFilters = Boolean(types || repo || author || date || branch)
  const showFilterControls = hasQuery || hasActiveFilters

  const typeCounts = useMemo(() => {
    if (data?.counts) {
      return {
        checkpoints: data.counts.checkpoints ?? 0,
        commits: data.counts.commits ?? 0,
        sessions: data.counts.sessions ?? 0,
      }
    }
    return {
      checkpoints: visibleResults.filter((r) => r.type === "checkpoint").length,
      commits: visibleResults.filter((r) => r.type === "commit").length,
      sessions: visibleResults.filter((r) => r.type === "session").length,
    }
  }, [data?.counts, visibleResults])

  const hasAnyTypeResults = typeCounts.checkpoints + typeCounts.commits + typeCounts.sessions > 0

  const selectedTypes = useMemo(() => {
    if (types) return types.split(",").filter(Boolean)
    if (typeCounts.checkpoints > 0) return ["checkpoints"]
    if (typeCounts.sessions > 0) return ["sessions"]
    if (typeCounts.commits > 0) return ["commits"]
    return ["checkpoints"]
  }, [types, typeCounts])

  const filtered = useMemo(() => {
    if (selectedTypes.length === 0) return visibleResults
    return visibleResults.filter((result) =>
      selectedTypes.includes(SEARCH_RESULT_TYPE_MAP[result.type] ?? result.type),
    )
  }, [visibleResults, selectedTypes])

  const showLoading =
    isQueryStale || isPending || (isFetching && (isPlaceholderData || allResults.length === 0))

  const sort: SortOption =
    sortParam === "date" || sortParam === "author" || sortParam === "title"
      ? sortParam
      : "relevance"

  const sorted = useMemo(
    () =>
      sort === "relevance"
        ? filtered
        : [...filtered].sort((a, b) => {
            if (sort === "date") {
              const getDate = (r: SearchResult) => {
                if (r.type === "checkpoint") return r.data.createdAt
                if (r.type === "commit") return r.data.createdAt
                if (r.type === "pr") return r.data.createdAt
                if (r.type === "session") return r.data.createdAt
                return ""
              }
              return getDate(b).localeCompare(getDate(a))
            }
            if (sort === "author") {
              const getAuthor = (r: SearchResult) => {
                if (r.type === "checkpoint") return r.data.authorUsername ?? r.data.author
                if (r.type === "commit") return r.data.authorUsername ?? r.data.author
                if (r.type === "pr") return r.data.userLogin ?? ""
                if (r.type === "session") return r.data.authorUsername ?? r.data.agent ?? ""
                return r.data.org
              }
              return getAuthor(a).localeCompare(getAuthor(b))
            }
            if (sort === "title") {
              const getTitle = (r: SearchResult) => {
                if (r.type === "checkpoint")
                  return checkpointTitle(r.data.prompt, r.data.commitSubject)
                if (r.type === "commit") return r.data.commitSubject
                if (r.type === "pr") return r.data.title
                if (r.type === "session") return r.data.displayName
                return r.data.fullName
              }
              return getTitle(a).localeCompare(getTitle(b))
            }
            return 0
          }),
    [filtered, sort],
  )

  const results = sorted

  // Repos present in results (for the repo filter dropdown).
  // Only computed when no repo filter is active so the dropdown shows what's available.
  const reposInResults = useMemo(() => {
    if (repo) return []
    const map = new Map<string, number>()
    for (const result of visibleResults) {
      if (result.type === "repo") continue
      const key = `${result.data.org}/${result.data.repo}`
      map.set(key, (map.get(key) ?? 0) + 1)
    }
    return [...map.entries()]
      .sort((a, b) => b[1] - a[1])
      .map(([fullName, count]) => ({ fullName, count }))
  }, [repo, visibleResults])

  // Branches present in results (for the branch filter dropdown).
  const branchesInResults = useMemo(() => {
    if (branch) return []
    const map = new Map<string, number>()
    for (const result of visibleResults) {
      if (result.type === "checkpoint" && result.data.branch) {
        map.set(result.data.branch, (map.get(result.data.branch) ?? 0) + 1)
      } else if (result.type === "commit" && result.data.branch) {
        map.set(result.data.branch, (map.get(result.data.branch) ?? 0) + 1)
      }
    }
    return [...map.entries()]
      .sort((a, b) => b[1] - a[1])
      .map(([branch, count]) => ({ branch, count }))
  }, [branch, visibleResults])

  function handleSelect(result: SearchResult) {
    posthog.capture("search_result_clicked", {
      query,
      source: "search_page",
      result_type: result.type,
      match_type: result.searchMeta.matchType,
      score: result.searchMeta.score,
      result_position: sorted.indexOf(result) + 1,
    })
    openSearchResult(navigate, result)
  }

  function trackFilter(filterName: string, value: string | undefined) {
    posthog.capture("search_filter_applied", {
      query,
      filter_name: filterName,
      filter_value: value ?? null,
    })
  }

  function clearAllFilters() {
    navigate({
      search: (prev) => ({
        ...prev,
        types: undefined,
        repo: undefined,
        author: undefined,
        date: undefined,
        branch: undefined,
      }),
    })
  }

  return (
    <Page breadcrumbs={[{ label: "Search" }]} noPadding>
      <div className="flex h-full flex-col">
        <div data-testid="search-toolbar" className="@container px-6 pt-6 pb-4">
          <div className="flex flex-col gap-2 @lg:flex-row @lg:items-start">
            <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
              <div
                data-testid="search-input-row"
                className="flex w-full min-w-0 items-center gap-2 @lg:w-auto"
              >
                <div
                  data-testid="search-input-wrap"
                  className="min-w-45 flex-1 @md:min-w-65 @lg:w-auto @lg:min-w-[320px] @lg:flex-none"
                >
                  <SearchInput
                    size="small"
                    placeholder="Search..."
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    loading={isFetching}
                  />
                </div>
                {showFilterControls && (
                  <div data-testid="search-filter-trigger" className="shrink-0">
                    <Dropdown>
                      <DropdownTrigger asChild>
                        <Button size="icon-small" aria-label="Filter">
                          <FilterIcon size={18} />
                        </Button>
                      </DropdownTrigger>
                      <DropdownContent>
                        {reposInResults.length > 0 && (
                          <DropdownSub>
                            <DropdownSubTrigger>Repository</DropdownSubTrigger>
                            <DropdownSubContent>
                              {reposInResults.map(({ fullName }) => (
                                <DropdownSubItem
                                  key={fullName}
                                  selected={repo === fullName}
                                  onClick={() => {
                                    trackFilter("repository", fullName)
                                    setRepo(fullName)
                                  }}
                                >
                                  {fullName.split("/")[1] ?? fullName}
                                </DropdownSubItem>
                              ))}
                            </DropdownSubContent>
                          </DropdownSub>
                        )}
                        <DropdownSub>
                          <DropdownSubTrigger>Date</DropdownSubTrigger>
                          <DropdownSubContent>
                            {(["week", "month"] as const).map((val) => (
                              <DropdownSubItem
                                key={val}
                                selected={date === val}
                                onClick={() => {
                                  trackFilter("date", val)
                                  setDate(val)
                                }}
                              >
                                {val === "week" ? "Past week" : "Past month"}
                              </DropdownSubItem>
                            ))}
                          </DropdownSubContent>
                        </DropdownSub>
                        {branchesInResults.length > 0 && (
                          <DropdownSub>
                            <DropdownSubTrigger>Branch</DropdownSubTrigger>
                            <DropdownSubContent>
                              {branchesInResults.map(({ branch: branchName }) => (
                                <DropdownSubItem
                                  key={branchName}
                                  selected={branch === branchName}
                                  onClick={() => {
                                    trackFilter("branch", branchName)
                                    setBranch(branchName)
                                  }}
                                >
                                  {branchName}
                                </DropdownSubItem>
                              ))}
                            </DropdownSubContent>
                          </DropdownSub>
                        )}
                        {hasActiveFilters && (
                          <>
                            <DropdownSeparator />
                            <DropdownItem onClick={clearAllFilters}>Clear all filters</DropdownItem>
                          </>
                        )}
                      </DropdownContent>
                    </Dropdown>
                  </div>
                )}
              </div>
              {showFilterControls && (
                <>
                  {/* Active filter pills */}
                  {repo && (
                    <FilterPill
                      label="Repository"
                      operator="is"
                      value={repo.split("/")[1] ?? repo}
                      values={reposInResults.map(
                        ({ fullName }) => fullName.split("/")[1] ?? fullName,
                      )}
                      onValueChange={(val) => {
                        const match = reposInResults.find(
                          ({ fullName }) => (fullName.split("/")[1] ?? fullName) === val,
                        )
                        if (match) {
                          trackFilter("repository", match.fullName)
                          setRepo(match.fullName)
                        }
                      }}
                      onRemove={() => setRepo("")}
                    />
                  )}
                  {date && (
                    <FilterPill
                      label="Date"
                      operator="is"
                      value={date === "week" ? "Past week" : "Past month"}
                      values={["Past week", "Past month"]}
                      onValueChange={(val) => {
                        const dateVal = val === "Past week" ? "week" : "month"
                        trackFilter("date", dateVal)
                        setDate(dateVal)
                      }}
                      onRemove={() => setDate("")}
                    />
                  )}
                  {branch && (
                    <FilterPill
                      label="Branch"
                      operator="is"
                      value={branch}
                      values={branchesInResults.map(({ branch }) => branch)}
                      onValueChange={(val) => {
                        trackFilter("branch", val)
                        setBranch(val)
                      }}
                      onRemove={() => setBranch("")}
                    />
                  )}
                </>
              )}
            </div>
            {/* Sort */}
            {hasQuery && (
              <div data-testid="search-sort" className="w-full @lg:w-auto @lg:shrink-0">
                <Dropdown>
                  <DropdownTrigger asChild>
                    <Button
                      size="small"
                      aria-label="Sort"
                      className="w-full justify-between @lg:w-auto @lg:justify-center"
                    >
                      <ArrowDownWideNarrow size={16} />
                      {sort === "relevance"
                        ? "Relevance"
                        : sort === "date"
                          ? "Date"
                          : sort === "author"
                            ? "Author"
                            : "Title"}
                      <ChevronDown size={14} className="text-disabled" />
                    </Button>
                  </DropdownTrigger>
                  <DropdownContent>
                    {(
                      [
                        ["relevance", "Relevance"],
                        ["date", "Date"],
                        ["author", "Author"],
                        ["title", "Title"],
                      ] as const
                    ).map(([value, label]) => (
                      <DropdownItem
                        key={value}
                        selected={sort === value}
                        checkPosition="end"
                        onClick={() => setSortParam(value)}
                      >
                        {label}
                      </DropdownItem>
                    ))}
                  </DropdownContent>
                </Dropdown>
              </div>
            )}
          </div>
        </div>

        {!hasQuery ? (
          <div className="flex flex-1 items-center justify-center px-6 pb-8">
            <div className="w-full max-w-lg text-center">
              {hasActiveFilters ? (
                <>
                  <p className="text-sm font-medium text-default">Enter a search query</p>
                  <p className="mt-2 mb-6 text-sm text-muted">
                    {repo
                      ? `Search within ${repo.split("/")[1] ?? repo} using the active filters.`
                      : "Search using the active filters."}
                  </p>
                  <button
                    onClick={clearAllFilters}
                    className="mb-6 cursor-pointer text-xs text-disabled underline underline-offset-2 hover:text-default"
                  >
                    Clear filters
                  </button>
                </>
              ) : (
                <p className="mb-6 text-sm text-muted">
                  Search across repos, checkpoints, and commit messages
                </p>
              )}

              {/* Recent searches as pills */}
              {!hasActiveFilters && recent.length > 0 && (
                <div className="mb-6">
                  <p className="mb-3 text-xs font-medium tracking-wide text-muted uppercase">
                    Recent
                  </p>
                  <div className="flex flex-wrap justify-center gap-2">
                    {recent.map((rq) => (
                      <button
                        key={rq}
                        onClick={() => setQueryImmediately(rq)}
                        className="flex cursor-pointer items-center gap-1.5 rounded-full border border-default bg-raised px-3 py-1 text-sm transition-colors hover:bg-hover"
                      >
                        <Clock className="size-3 text-muted" />
                        {rq}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {!hasActiveFilters && recent.length === 0 && (
                <p className="text-xs text-muted">
                  Press{" "}
                  <kbd className="rounded-lg border border-default bg-raised px-1.5 py-0.5 font-mono text-[11px]">
                    /
                  </kbd>{" "}
                  to start searching
                </p>
              )}
            </div>
          </div>
        ) : (
          <>
            {/* Type pills */}
            <div className="px-6 pb-4">
              <ButtonGroup size="small">
                {(["Checkpoints", "Sessions", "Commits"] as const).map((label) => {
                  const typeMap: Record<string, string> = {
                    Sessions: "sessions",
                    Checkpoints: "checkpoints",
                    Commits: "commits",
                  }
                  const value = typeMap[label]
                  const isActive = selectedTypes.includes(value)
                  const count =
                    label === "Sessions"
                      ? typeCounts.sessions
                      : label === "Checkpoints"
                        ? typeCounts.checkpoints
                        : typeCounts.commits
                  return (
                    <Button
                      key={label}
                      size="small"
                      variant="outline"
                      className={isActive ? "bg-muted! font-semibold" : undefined}
                      onClick={() => {
                        trackFilter("types", value)
                        navigate({
                          search: (prev) => ({ ...prev, types: value }),
                        })
                      }}
                    >
                      {label}
                      {hasAnyTypeResults && !isQueryStale && (
                        <span className="text-xs opacity-60">{count}</span>
                      )}
                    </Button>
                  )
                })}
              </ButtonGroup>
            </div>

            <div className="flex-1 overflow-y-auto px-6 pb-4">
              {/* Results */}
              {(showLoading || results.length > 0) && (
                <div className="flex flex-col overflow-hidden rounded-lg border border-default bg-raised">
                  {showLoading
                    ? Array.from({ length: 12 }).map((_, i) => (
                        <div
                          key={i}
                          className="flex h-16 items-center gap-4 border-b border-default px-4 last:border-b-0"
                        >
                          <Skeleton className="size-6 shrink-0 rounded-lg" />
                          <div className="flex min-w-0 flex-1 flex-col gap-1">
                            <Skeleton className="h-4 w-2/3" />
                            <Skeleton className="h-3 w-1/3" />
                          </div>
                          <Skeleton className="h-3 w-24 shrink-0" />
                        </div>
                      ))
                    : results.map((r) => (
                        <SearchResultCard
                          key={`${r.type}-${r.type === "session" ? `${r.data.org}/${r.data.repo}:${r.data.sessionId}` : r.data.id}`}
                          result={r}
                          onClick={() => handleSelect(r)}
                        />
                      ))}
                </div>
              )}

              {/* Error state */}
              {!showLoading && isError && (
                <div className="flex flex-col items-center justify-center py-16 text-center">
                  <p className="text-sm font-medium text-default">Search failed</p>
                  <p className="mt-1 text-xs text-disabled">
                    Something went wrong — please try again
                  </p>
                </div>
              )}

              {/* Empty state: selected type tab has no results but other types do */}
              {!showLoading && results.length === 0 && data !== undefined && hasAnyTypeResults && (
                <div className="flex flex-col items-center justify-center py-16 text-center">
                  <p className="text-sm font-medium text-default">
                    No {selectedTypes[0] ?? "results"} found{" "}
                  </p>
                  <p className="mt-1 text-xs text-disabled">Try switching to a different tab</p>
                </div>
              )}

              {/* Empty state: API returned no results for this query across all types */}
              {!showLoading &&
                !isError &&
                results.length === 0 &&
                query.trim().length > 0 &&
                data !== undefined &&
                !hasAnyTypeResults && (
                  <div className="flex flex-col items-center justify-center py-16 text-center">
                    <p className="text-sm font-medium text-default">
                      No results for &ldquo;{query}&rdquo;
                    </p>
                    <p className="mt-1 text-xs text-disabled">
                      {hasActiveFilters
                        ? "Try clearing some filters or using different keywords"
                        : "Try different keywords or a broader search term"}
                    </p>
                    {hasActiveFilters && (
                      <button
                        onClick={clearAllFilters}
                        className="mt-3 cursor-pointer text-xs text-disabled underline underline-offset-2 hover:text-default"
                      >
                        Clear all filters
                      </button>
                    )}
                  </div>
                )}
            </div>
          </>
        )}
      </div>
    </Page>
  )
}

import { keepPreviousData, useQuery } from "@tanstack/react-query"
import { usePostHog } from "posthog-js/react"

import { globalSearchQuery } from "../api"
import type { GlobalSearchParams, SearchResponse } from "../types"

interface UseGlobalSearchQueryOptions {
  source: "search_page" | "command_palette"
}

export function useGlobalSearchQuery(
  params: GlobalSearchParams | null,
  options: UseGlobalSearchQueryOptions,
) {
  const posthog = usePostHog()

  return useQuery<SearchResponse>({
    queryKey: ["global-search", params],
    queryFn: async () => {
      const start = performance.now()
      const response = await globalSearchQuery(params!)
      const clientMs = Math.round(performance.now() - start)

      if (params?.q.trim()) {
        posthog.capture("search_executed", {
          query: params.q,
          query_length: params.q.length,
          source: options.source,
          result_count: response.total ?? response.results.length,
          client_latency_ms: clientMs,
          timing_total_ms: response.timing?.total_ms ?? null,
          timing_keyword_ms: response.timing?.keyword_ms ?? null,
          timing_embedding_ms: response.timing?.embedding_ms ?? null,
          timing_vector_ms: response.timing?.vector_ms ?? null,
          timing_rerank_ms: response.timing?.rerank_ms ?? null,
        })
      }

      return response
    },
    enabled: params !== null && params.q.trim().length > 0,
    staleTime: 5 * 60_000,
    gcTime: 10 * 60_000,
    placeholderData: keepPreviousData,
  })
}

