// ─── Auth helper: session cookie → Entire API token → GitHub token ────────────

async function resolveUserId(
  c: SearchContext,
): Promise<{ userId: string; login?: string } | Response> {
  // 1. Try session cookie (frontend)
  const sessionToken = getCookie(c, "session")
  if (sessionToken) {
    const session = await getSession(c.env.ENTIRE_CACHE, sessionToken)
    if (session) {
      return { userId: session.userId }
    }
  }

  // 2. Extract Bearer/token from Authorization header
  const authHeader = c.req.header("Authorization")
  if (!authHeader) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const token = authHeader.replace(/^(token|Bearer)\s+/i, "")
  if (!token) {
    return c.json({ error: "Invalid authorization header" }, 401)
  }

  // 3. Try Entire API token (ent_*) — keep this disjoint from JWT validation.
  if (token.startsWith(API_TOKEN_PREFIX)) {
    const hash = await sha256Hex(token)
    const db = getKysely({ HYPERDRIVE: c.env.HYPERDRIVE_BACKGROUND })
    const apiTokens = createApiTokensNamespace(db)
    const lookup = await apiTokens.findByTokenHash(hash)

    if (!lookup) {
      return c.json({ error: "Invalid or expired token" }, 401)
    }

    if (new Date(lookup.expires_at) < new Date()) {
      return c.json({ error: "Token expired" }, 401)
    }
    const updateLastUsed = () =>
      Promise.resolve()
        .then(() => apiTokens.updateLastUsedAt(lookup.id))
        .catch((err) => {
          console.error("[search] update_last_used_failed:", err)
        })

    try {
      c.executionCtx.waitUntil(updateLastUsed())
    } catch {
      void updateLastUsed()
    }

    recordSpanAttributes({ "auth.bearer_type": "ent" })
    return { userId: lookup.user_id }
  }

  // 4. Try entire-core JWT (issued by the IdP at $ENTIRE_CORE_BASE_URL)
  const looksLikeJwt = token.split(".").length === 3
  const coreConfig = getCoreBearerConfig(c.env)
  if (coreConfig && looksLikeJwt) {
    const db = getKysely({ HYPERDRIVE: c.env.HYPERDRIVE_BACKGROUND })
    const principal = await validateCoreJwt(token, coreConfig, async (githubId) => {
      const user = await getUserByGithubId(db, githubId)
      return user ? { id: user.id } : null
    })
    if (principal) {
      recordSpanAttributes({ "auth.bearer_type": "jwt" })
      return { userId: principal.userId }
    }
    // JWT-shaped token failed validation. Reason already logged inside
    // validateCoreJwt; do not waste a GitHub API call probing it.
    return c.json({ error: "Invalid or expired token" }, 401)
  }

  // 5. Fall back to GitHub token
  const ghUser = await getAuthenticatedUser(token)
  const db = getKysely({ HYPERDRIVE: c.env.HYPERDRIVE_BACKGROUND })
  const user = await getUserByGithubId(db, ghUser.id)

  if (!user) {
    return c.json({ error: "User not found in Entire" }, 404)
  }

  return { userId: user.id, login: ghUser.login }
}

// ─── Unified search ───────────────────────────────────────────────────────────
app.get("/search/v1/search", async (c) => {
  const q = c.req.query("q")
  const typesParam = c.req.query("types")
  const repo = c.req.query("repo")
  const branch = c.req.query("branch")
  const author = c.req.query("author")
  const dateParam = c.req.query("date")
  const pageParam = c.req.query("page")
  const limitParam = c.req.query("limit")
  const modeParam = c.req.query("mode")
  const filterTypeParam = c.req.query("filter_type")

  if (!q) {
    return c.json({ error: "Query parameter 'q' is required" }, 400)
  }

  const trimmedQ = q.trim()
  if (!trimmedQ) {
    return c.json({ error: "Query must contain non-whitespace characters" }, 400)
  }

  const MAX_QUERY_LENGTH = 500
  if (trimmedQ.length > MAX_QUERY_LENGTH) {
    return c.json({ error: `Query too long (max ${MAX_QUERY_LENGTH} characters)` }, 400)
  }

  const MAX_BRANCH_LENGTH = 250
  if (branch && branch.length > MAX_BRANCH_LENGTH) {
    return c.json({ error: `Branch name too long (max ${MAX_BRANCH_LENGTH} characters)` }, 400)
  }

  const validDates = ["week", "month"]
  if (dateParam && !validDates.includes(dateParam)) {
    return c.json(
      { error: `Invalid date value '${dateParam}'. Must be one of: ${validDates.join(", ")}` },
      400,
    )
  }

  const validModes = ["hybrid", "keyword"]
  if (modeParam && !validModes.includes(modeParam)) {
    return c.json(
      { error: `Invalid mode '${modeParam}'. Must be one of: ${validModes.join(", ")}` },
      400,
    )
  }
  const mode = (modeParam as "hybrid" | "keyword") || undefined

  const validFilterTypes = ["checkpoints", "commits", "sessions"]
  if (filterTypeParam && !validFilterTypes.includes(filterTypeParam)) {
    return c.json(
      {
        error: `Invalid filter_type '${filterTypeParam}'. Must be one of: ${validFilterTypes.join(", ")}`,
      },
      400,
    )
  }
  const filterType = (filterTypeParam as "checkpoints" | "commits" | "sessions") || undefined

  const validTypes = ["repos", "checkpoints", "commits", "prs", "sessions"]
  const parsedTypes = typesParam
    ? (typesParam.split(",").filter((t) => validTypes.includes(t)) as (
        | "repos"
        | "checkpoints"
        | "commits"
        | "prs"
        | "sessions"
      )[])
    : undefined
  const types = parsedTypes?.length ? parsedTypes : undefined

  const limitRaw = limitParam ? parseInt(limitParam, 10) : 20
  const limit = Math.max(1, Math.min(Number.isNaN(limitRaw) ? 20 : limitRaw, 500))
  const perType = { repos: Math.min(limit, 20), checkpoints: limit }

  const posthog = createPostHogClient(c.env)

  try {
    const authResult = await resolveUserId(c)
    if (authResult instanceof Response) return authResult
    const { userId, login } = authResult

    const db = getKysely({ HYPERDRIVE: c.env.HYPERDRIVE_BACKGROUND })

    console.log(
      `[search] request`,
      JSON.stringify({
        user: login ?? userId,
        queryLength: trimmedQ.length,
        limit,
        types: types ?? ["repos", "checkpoints", "commits", "prs", "sessions"],
      }),
    )

    // Semantic search enabled if API keys present AND PostHog is configured for flag gating
    // Keyword-only mode only needs Turbopuffer (no Cohere embeddings)
    const semanticEnabled =
      mode === "keyword"
        ? !!c.env.TURBOPUFFER_API_KEY
        : !!(c.env.TURBOPUFFER_API_KEY && c.env.COHERE_API_KEY && posthog)

    const svc = new SearchService(
      db,
      c.env.TURBOPUFFER_API_KEY,
      undefined, // legacy openai slot
      semanticEnabled,
      c.env.SEARCH_CACHE,
      posthog,
      c.env.COHERE_API_KEY,
      isLocalDev(c.env),
    )

    const result: SearchResponse = await svc.search(userId, {
      q: trimmedQ,
      types,
      repo,
      branch: branch || undefined,
      author,
      date: dateParam as "week" | "month" | undefined,
      page: (() => {
        const p = pageParam ? parseInt(pageParam, 10) : 1
        return Number.isNaN(p) ? 1 : p
      })(),
      limit,
      perType,
      mode,
      filterType,
    })

    // Shutdown PostHog client to stop polling timers (non-blocking)
    c.executionCtx.waitUntil(shutdownPostHogClient(posthog))

    return c.json(result)
  } catch (err) {
    c.executionCtx.waitUntil(shutdownPostHogClient(posthog))
    if (err instanceof AuthError) {
      return c.json({ error: "Invalid or expired GitHub token" }, 401)
    }
    if (err instanceof NotFoundError) {
      return c.json({ error: (err as Error).message }, 404)
    }
    if (isCoreJwtUnavailableError(err)) {
      return c.json({ error: "Authentication service unavailable" }, 503)
    }
    console.error(`[search] error:`, err)
    const showMessage = isLocalDev(c.env)
    return c.json(
      {
        error: "Search failed",
        message: showMessage ? (err as Error).message : undefined,
      },
      500,
    )
  }
})

// 404 handler
app.notFound((c) => c.json({ error: "Not found" }, 404))

// Error handler
app.onError((err, c) => {
  if (err instanceof HTTPException && err.status < 500) {
    if (err.res) {
      return err.getResponse()
    }
    return c.json({ error: err.message || "Bad request" }, err.status)
  }
  console.error("Unhandled error:", err)
  const showMessage = isLocalDev(c.env)
  return c.json(
    {
      error: "Internal server error",
      message: showMessage ? err.message : undefined,
    },
    500,
  )
})

// OpenTelemetry configuration — mirrors the main API worker (api/src/index.ts).
// Exports traces only when OTEL_EXPORTER_OTLP_ENDPOINT is set and not local dev.
// Gate on development-only here (NOT this worker's isLocalDev, which also treats
// staging as local for CORS/error-verbosity) so staging exports traces just like
// the main API — whose isLocalDev is development-only.
const otelConfig: ResolveConfigFn = (env: Env) =>
  buildOtelConfig({
    endpoint: env.OTEL_EXPORTER_OTLP_ENDPOINT,
    headers: env.OTEL_EXPORTER_OTLP_HEADERS,
    serviceName: "entire-search",
    localDev: env.ENVIRONMENT === "development",
  })

export default instrument(
  {
    fetch: app.fetch,
  },
  otelConfig,
)

// SearchService: orchestrates unified search across repos, checkpoints, commits, and PRs.
// All full-text and semantic search goes through a single Turbopuffer query per org namespace.
// Tier-based pipeline: tier 0 (full keyword match), tier 1 (partial + top ANN, Cohere reranked),
// tier 2 (remaining ANN, capped).

import type { PostHog } from "posthog-node"

import { parseCommitMessage } from "./commit-message"
import { getAccessibleReposByUser, searchReposByUser } from "./planetscale/repos"
import { isFeatureEnabled } from "./posthog"
import { rerankTier1 } from "./search-reranker"
import type {
  SearchMatchType,
  SearchResult,
  SearchResponse,
  SearchParams,
  SearchTier,
  CheckpointResult,
  CommitResult,
  PRResult,
  SessionResult,
} from "./search-types"
import type { UnifiedSearchRow } from "./turbopuffer"
import { embedQueryVector, searchChunksOrg } from "./turbopuffer"

export type { SearchResult, SearchResponse, SearchParams }

// Normalize branch from turbopuffer (stored as string[]).
function normalizeBranch(branch: string[] | undefined): string {
  return branch?.[0] ?? ""
}

function safeJsonParse(str: string): string[] {
  try {
    const parsed = JSON.parse(str)
    return Array.isArray(parsed) ? parsed : []
  } catch {
    return []
  }
}

// BM25 scores: higher is better. ANN cosine distance: lower is better.
// Prefer BM25 hit over ANN-only, then best score within the same type.
function isBetterHit(
  candidate: { bm25Score: number | null; score: number },
  existing: { bm25Score: number | null; score: number } | undefined,
): boolean {
  return (
    !existing ||
    (candidate.bm25Score !== null && existing.bm25Score === null) ||
    (candidate.bm25Score !== null &&
      existing.bm25Score !== null &&
      candidate.score > existing.score) ||
    (candidate.bm25Score === null &&
      existing.bm25Score === null &&
      candidate.score < existing.score)
  )
}

// Max concurrent org namespace queries
const ORG_QUERY_CONCURRENCY = 5

// Tier pipeline constants
const MAX_TIER2 = 15 // cap on tier 2 results

// Check if the full query phrase appears in any of the Turbopuffer text fields.
// For single-word queries, this checks for the word. For multi-word, checks the
// exact phrase in order.
function isFullQueryMatch(query: string, hit: UnifiedSearchRow): boolean {
  const q = query.toLowerCase()
  for (const text of [hit.title_text, hit.meta_text, hit.chunk_text]) {
    if (text && text.toLowerCase().includes(q)) return true
  }
  return false
}

// Assign tier and matchType from Turbopuffer hit data
function assignHitTier(
  query: string,
  hit: UnifiedSearchRow,
): { tier: SearchTier; matchType: SearchMatchType } {
  let tier: SearchTier
  if (hit.bm25Score !== null && isFullQueryMatch(query, hit)) {
    tier = 0
  } else if (hit.bm25Score !== null) {
    tier = 1 // BM25 matched but only partial
  } else {
    tier = 2 // ANN-only, will be promoted to tier 1 or capped later
  }

  const matchType: SearchMatchType =
    hit.bm25Score !== null && hit.annScore !== null
      ? "both"
      : hit.bm25Score !== null
        ? "keyword"
        : "semantic"

  return { tier, matchType }
}

// Apply a small recency boost to BM25 scores (higher = better).
// Skipped for ANN-only results where lower cosine distance = better.
function applyRecencyBoost(score: number, createdAt: string, isAnnOnly: boolean): number {
  if (isAnnOnly || !createdAt) return score
  const ageDays = (Date.now() - new Date(createdAt).getTime()) / (1000 * 60 * 60 * 24)
  return score * (1.0 + 0.1 * Math.max(0, 1 - ageDays / 30))
}

// ─── SearchService ────────────────────────────────────────────────────────────

export class SearchService {
  constructor(
    private readonly db: any,
    private readonly turbopufferApiKey: string | undefined,
    _unused: string | undefined, // legacy openai slot, kept for positional compat
    private readonly semanticSearchEnabled: boolean,
    private readonly cache?: KVNamespace,
    private readonly posthog?: PostHog | null,
    private readonly cohereApiKey?: string,
    private readonly skipFeatureFlags?: boolean,
  ) {}

  async search(userId: string, params: SearchParams): Promise<SearchResponse> {
    const totalStart = Date.now()
    const { types = ["repos", "checkpoints", "commits", "prs", "sessions"] } = params
    const allResults: SearchResult[] = []

    let embedding_ms: number | null = null
    let vector_ms: number | null = null
    let fanout_ms: number | null = null
    let session_hydration_ms: number | null = null
    let rerank_ms: number | null = null
    let reranked: boolean | undefined

    const repoSearchStart = Date.now()
    if (types.includes("repos")) {
      const repos = await this.searchRepos(userId, params)
      allResults.push(...repos)
    }
    const repoSearch_ms = Date.now() - repoSearchStart

    // Unified search covers checkpoints, commits, PRs, and sessions via Turbopuffer.
    // Sessions and commits are also derived from checkpoint hits, so ensure
    // checkpoints are always queried when either is requested.
    const wantsSessions = types.includes("sessions")
    const wantsCommits = types.includes("commits")
    const searchTypes = types.filter((t) => t !== "repos" && t !== "sessions")
    if ((wantsSessions || wantsCommits) && !searchTypes.includes("checkpoints")) {
      searchTypes.push("checkpoints")
    }
    const isKeywordOnly = params.mode === "keyword"
    if (searchTypes.length > 0 && this.semanticSearchEnabled) {
      let queryVector: number[] | undefined
      if (!isKeywordOnly) {
        const embedStart = Date.now()
        queryVector = await embedQueryVector(this.cohereApiKey!, params.q)
        embedding_ms = Date.now() - embedStart
      }

      const vectorStart = Date.now()
      const unified = await this.searchUnified(
        userId,
        params,
        queryVector,
        searchTypes,
        wantsSessions,
        wantsCommits,
      )
      vector_ms = Date.now() - vectorStart
      fanout_ms = unified.fanout_ms
      session_hydration_ms = unified.session_hydration_ms
      // If sessions were requested but checkpoints were not, remove checkpoint
      // results that were only fetched to derive sessions.
      const wantsCheckpoints = types.includes("checkpoints")
      for (const r of unified.results) {
        if (r.type === "checkpoint" && !wantsCheckpoints) continue
        allResults.push(r)
      }
    }

    // ─── Keyword-only fast path ──────────────────────────────────────────────
    // BM25 results are already ranked by turbopuffer's weighted BM25 scoring.
    // No embeddings, no Cohere reranking, no tier promotion — just sort by
    // BM25 score and return. This keeps keyword search nearly instant.
    let finalResults: SearchResult[]
    if (isKeywordOnly) {
      allResults.sort((a, b) => (b.searchMeta.bm25Score ?? 0) - (a.searchMeta.bm25Score ?? 0))
      finalResults = allResults
    } else {
      // ─── Semantic/hybrid tier pipeline ───────────────────────────────────────
      // Separate into tiers
      const tier0: SearchResult[] = []
      const tier1: SearchResult[] = []
      let tier2: SearchResult[] = []
      const repoResults: SearchResult[] = []

      for (const r of allResults) {
        if (r.type === "repo") {
          repoResults.push(r)
          continue
        }
        if (r.searchMeta.tier === 0) tier0.push(r)
        else if (r.searchMeta.tier === 1) tier1.push(r)
        else tier2.push(r)
      }

      // Tier 0: sort by bm25Score desc (no rerank)
      tier0.sort((a, b) => (b.searchMeta.bm25Score ?? 0) - (a.searchMeta.bm25Score ?? 0))

      // Cohere relevance threshold: 0.3 baseline, may tighten later once we
      // have more data on score distributions.
      const hasKeywordMatches = tier0.length > 0
      const minRelevance = hasKeywordMatches ? 0.3 : 0.2

      // Tier 1: Cohere rerank with relevance threshold (hybrid/semantic only)
      if (this.cohereApiKey && tier1.length > 0) {
        const rerankStart = Date.now()
        const rerankOutput = await rerankTier1(
          this.cohereApiKey,
          params.q,
          tier1,
          minRelevance,
          this.cache,
        )
        rerank_ms = Date.now() - rerankStart
        reranked = rerankOutput.reranked
        tier1.splice(0, tier1.length, ...rerankOutput.results)
      }

      // Append top 10% of ANN-only results (tier 2) after Cohere-reranked tier 1.
      let promoted: SearchResult[] = []
      if (this.cohereApiKey && tier2.length > 0) {
        tier2.sort((a, b) => a.searchMeta.score - b.searchMeta.score)
        const promotionCount = Math.max(1, Math.ceil(tier2.length * 0.1))
        promoted = tier2.splice(0, promotionCount)
        tier1.push(...promoted)
      }

      // Tier 2: only show when tier 0+1 are empty (nothing relevant found).
      if (tier0.length > 0 || tier1.length > 0) {
        tier2 = []
      } else {
        tier2.unshift(...promoted)
        tier2.sort(
          (a, b) =>
            (a.searchMeta.annScore ?? a.searchMeta.score) -
            (b.searchMeta.annScore ?? b.searchMeta.score),
        )
        tier2.splice(MAX_TIER2)
      }

      // Diagnostic log
      console.log(
        `[search] tier_distribution`,
        JSON.stringify({
          tier0: tier0.length,
          tier1: tier1.length,
          tier2: tier2.length,
          repos: repoResults.length,
          minRelevance,
        }),
      )

      // Combine: [repos] + [tier 0] + [tier 1] + [tier 2]
      finalResults = [...repoResults, ...tier0, ...tier1, ...tier2]
    }

    // Compute per-type counts from the full result set (before filtering/pagination)
    const counts = { repos: 0, checkpoints: 0, commits: 0, prs: 0, sessions: 0 }
    for (const r of finalResults) {
      if (r.type === "repo") counts.repos++
      else if (r.type === "checkpoint") counts.checkpoints++
      else if (r.type === "commit") counts.commits++
      else if (r.type === "pr") counts.prs++
      else if (r.type === "session") counts.sessions++
    }

    // Filter by type tab selection (after counts, before pagination)
    const typeMap: Record<string, SearchResult["type"]> = {
      checkpoints: "checkpoint",
      commits: "commit",
      sessions: "session",
    }
    const filtered = params.filterType
      ? finalResults.filter((r) => r.type === typeMap[params.filterType!])
      : finalResults

    const total = filtered.length
    const safePage = Math.max(1, params.page)
    const start = (safePage - 1) * params.limit

    const results = filtered.slice(start, start + params.limit)
    const total_ms = Date.now() - totalStart

    console.log(
      `[search] timing_breakdown`,
      JSON.stringify({
        total_ms,
        repoSearch_ms,
        embedding_ms,
        vector_ms,
        fanout_ms,
        session_hydration_ms,
        rerank_ms,
        resultCount: finalResults.length,
      }),
    )

    return {
      results,
      total,
      page: safePage,
      timing: {
        total_ms,
        keyword_ms: null,
        embedding_ms,
        vector_ms,
        rerank_ms,
        fanout_ms,
        session_hydration_ms,
      },
      ...(reranked !== undefined && { reranked }),
      counts,
    }
  }

  private async searchUnified(
    userId: string,
    params: SearchParams,
    queryVector: number[] | undefined,
    searchTypes: string[],
    wantsSessions: boolean,
    wantsCommits: boolean,
  ): Promise<{ results: SearchResult[]; fanout_ms: number; session_hydration_ms: number }> {
    const repoStart = Date.now()
    const repos = await getAccessibleReposByUser(this.db, userId, params.repo)
    console.log(
      `[search] accessible_repos`,
      JSON.stringify({
        count: repos.length,
        durationMs: Date.now() - repoStart,
        repoFilter: params.repo ?? null,
      }),
    )
    if (repos.length === 0) return { results: [], fanout_ms: 0, session_hydration_ms: 0 }

    let totalSessionHydrationMs = 0

    // Keyword-only mode can use a higher limit since there's no ANN/reranking overhead
    const maxChunks = params.mode === "keyword" ? 500 : 200
    const chunkLimit = Math.min(Math.max(params.perType.checkpoints * 5, 50), maxChunks)

    // Map search types to doc_types for Turbopuffer filter
    const docTypeMap: Record<string, string[]> = {
      checkpoints: ["checkpoint_chunk", "checkpoint_analysis"],
      commits: ["commit"],
      prs: ["pr"],
    }
    const docTypes = searchTypes.flatMap((t) => docTypeMap[t] ?? [])

    // Group accessible repos by org name for fan-out
    const byOrg = new Map<string, { repoIds: string[]; repoGithubIds: number[] }>()
    for (const repo of repos) {
      const orgName = repo.full_name.split("/")[0] ?? ""
      if (!orgName) continue
      const entry = byOrg.get(orgName) ?? { repoIds: [], repoGithubIds: [] }
      entry.repoIds.push(repo.id)
      entry.repoGithubIds.push(repo.github_id)
      byOrg.set(orgName, entry)
    }

    // Only search orgs explicitly enabled by PostHog flag.
    // In local dev, skip the flag check entirely so all orgs are searchable.
    // Flag checks are parallelized to avoid serializing N network/KV lookups.
    const orgEntries = [...byOrg.entries()]
    let orgs: Array<[string, { repoIds: string[]; repoGithubIds: number[] }]>

    if (this.skipFeatureFlags) {
      orgs = orgEntries
    } else {
      const flagStart = Date.now()
      const flagResults = await Promise.all(
        orgEntries.map(([orgName]) =>
          isFeatureEnabled(this.posthog ?? null, "semantic-search-api", orgName.toLowerCase()),
        ),
      )
      orgs = orgEntries.filter((_, i) => flagResults[i] === true)
      console.log(
        `[search] feature_flag_check`,
        JSON.stringify({
          totalOrgs: orgEntries.length,
          enabledOrgs: orgs.length,
          durationMs: Date.now() - flagStart,
        }),
      )
    }

    // Fan out to org namespaces with concurrency cap
    const allHits: UnifiedSearchRow[] = []
    const fanoutStart = Date.now()

    for (let i = 0; i < orgs.length; i += ORG_QUERY_CONCURRENCY) {
      const slice = orgs.slice(i, i + ORG_QUERY_CONCURRENCY)
      const sliceResults = await Promise.all(
        slice.map(([orgName, { repoGithubIds }]) =>
          searchChunksOrg(
            this.turbopufferApiKey!,
            this.cohereApiKey!,
            orgName,
            params.q,
            repoGithubIds,
            {
              branch: params.branch,
              docTypes: docTypes.length > 0 ? docTypes : undefined,
            },
            chunkLimit,
            this.cache,
            queryVector,
            params.mode ?? "hybrid",
          ),
        ),
      )
      for (const hits of sliceResults) {
        allHits.push(...hits)
      }
    }

    const totalFanoutMs = Date.now() - fanoutStart

    console.log(
      `[search] turbopuffer_fanout`,
      JSON.stringify({
        orgCount: orgs.length,
        hitCount: allHits.length,
        durationMs: totalFanoutMs,
      }),
    )

    if (allHits.length === 0)
      return { results: [], fanout_ms: totalFanoutMs, session_hydration_ms: 0 }

    // Group hits by doc_type
    const checkpointHits: UnifiedSearchRow[] = []
    const commitHits: UnifiedSearchRow[] = []
    const prHits: UnifiedSearchRow[] = []

    for (const hit of allHits) {
      if (hit.doc_type === "checkpoint_chunk" || hit.doc_type === "checkpoint_analysis") {
        checkpointHits.push(hit)
      } else if (hit.doc_type === "commit") {
        commitHits.push(hit)
      } else if (hit.doc_type === "pr") {
        prHits.push(hit)
      }
    }

    const bm25HitCount = allHits.filter((h) => h.bm25Rank !== null).length
    const annOnlyCount = allHits.filter((h) => h.bm25Rank === null).length
    console.log(
      `[search] hit_distribution`,
      JSON.stringify({
        total: allHits.length,
        checkpoints: checkpointHits.length,
        commits: commitHits.length,
        prs: prHits.length,
        withBm25: bm25HitCount,
        annOnly: annOnlyCount,
      }),
    )

    const results: SearchResult[] = []

    // Build repo_github_id → full_name lookup from the repos we already fetched for ACL
    const repoByGithubId = new Map<number, string>()
    for (const repo of repos) {
      repoByGithubId.set(repo.github_id, repo.full_name)
    }

    // Helper: resolve org/repo from turbopuffer hit's repo_github_id
    const resolveOrgRepo = (hit: UnifiedSearchRow): [string, string] | null => {
      if (!hit.repo_github_id) return null
      const fullName = repoByGithubId.get(hit.repo_github_id)
      if (!fullName) return null
      const parts = fullName.split("/")
      return [parts[0] ?? "", parts[1] ?? ""]
    }

    // ─── Dedup checkpoint chunks → best hit per checkpoint ───
    const bestByCheckpoint = new Map<string, UnifiedSearchRow>()
    for (const hit of checkpointHits) {
      if (!hit.checkpoint_id) continue
      const existing = bestByCheckpoint.get(hit.checkpoint_id)
      if (isBetterHit(hit, existing)) {
        bestByCheckpoint.set(hit.checkpoint_id, hit)
      }
    }

    // ─── Process checkpoints (directly from turbopuffer attributes) ───
    for (const [cpId, hit] of bestByCheckpoint) {
      const orgRepo = resolveOrgRepo(hit)
      if (!orgRepo) continue
      if (params.author && hit.author !== params.author) continue
      if (params.date) {
        const threshold =
          params.date === "week"
            ? new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
            : new Date(Date.now() - 30 * 24 * 60 * 60 * 1000)
        if (!hit.created_at || new Date(hit.created_at) < threshold) continue
      }

      // title_text was built as [prompt, commit_message].filter(Boolean).join("\n").
      // When prompt is null, title_text is just the commit message (no separator),
      // so we can't reliably split. Use a heuristic: if there's a newline, the
      // first part is the prompt and the rest is the commit message; otherwise
      // treat the whole string as the prompt (commit message stays null).
      const rawTitle = hit.title_text ?? ""
      const nlIndex = rawTitle.indexOf("\n")
      const prompt = nlIndex >= 0 ? rawTitle.slice(0, nlIndex) : rawTitle
      const commitMessage = nlIndex >= 0 ? rawTitle.slice(nlIndex + 1) : null
      const { subject } = parseCommitMessage(commitMessage)
      const data: CheckpointResult = {
        id: cpId,
        prompt,
        commitMessage,
        commitSubject: subject,
        commitSha: hit.commit_sha ?? null,
        branch: normalizeBranch(hit.branch),
        org: orgRepo[0],
        repo: orgRepo[1],
        author: hit.author ?? "",
        authorUsername: hit.author ?? null,
        createdAt: hit.created_at ?? "",
        filesTouched: hit.files_touched ? safeJsonParse(hit.files_touched) : [],
      }
      const { tier, matchType } = assignHitTier(params.q, hit)
      const baseScore = hit.bm25Score ?? hit.annScore ?? 0
      const score = applyRecencyBoost(baseScore, data.createdAt, hit.bm25Score === null)
      results.push({
        type: "checkpoint",
        data,
        searchMeta: {
          matchType,
          score,
          tier,
          snippet: hit.chunk_text,
          bm25Score: hit.bm25Score,
          annScore: hit.annScore,
          bm25Rank: hit.bm25Rank,
          annRank: hit.annRank,
        },
      })
    }

    // ─── Process commits (directly from turbopuffer attributes) ───
    // Merge indexed commits with projected commits from checkpoint hits
    const bestCommitBySha = new Map<string, UnifiedSearchRow>()
    for (const hit of commitHits) {
      const sha = hit.doc_id.split(":")[2]
      if (!sha) continue
      const existing = bestCommitBySha.get(sha)
      if (isBetterHit(hit, existing)) bestCommitBySha.set(sha, hit)
    }
    if (wantsCommits) {
      for (const [, hit] of bestByCheckpoint) {
        if (!hit.commit_sha) continue
        const existing = bestCommitBySha.get(hit.commit_sha)
        if (isBetterHit(hit, existing)) bestCommitBySha.set(hit.commit_sha, hit)
      }
    }

    for (const [sha, hit] of bestCommitBySha) {
      const orgRepo = resolveOrgRepo(hit)
      if (!orgRepo) continue
      // For indexed commit docs, title_text is the raw commit message.
      // For checkpoint-projected commits, title_text is "prompt\ncommit_message",
      // so extract only the commit message portion (after the newline).
      let commitMsg = hit.title_text ?? ""
      if (hit.doc_type === "checkpoint_chunk") {
        const nlIdx = commitMsg.indexOf("\n")
        commitMsg = nlIdx >= 0 ? commitMsg.slice(nlIdx + 1) : ""
      }
      const { subject } = parseCommitMessage(commitMsg)
      const data: CommitResult = {
        id: sha,
        commitSha: sha,
        commitMessage: commitMsg,
        commitSubject: subject ?? "",
        branch: normalizeBranch(hit.branch),
        org: orgRepo[0],
        repo: orgRepo[1],
        author: hit.author ?? "",
        authorUsername: hit.author ?? null,
        createdAt: hit.created_at ?? "",
        additions: 0,
        deletions: 0,
        filesChanged: 0,
        htmlUrl: null,
      }
      const { tier, matchType } = assignHitTier(params.q, hit)
      const baseScore = hit.bm25Score ?? hit.annScore ?? 0
      const score = applyRecencyBoost(baseScore, data.createdAt, hit.bm25Score === null)
      results.push({
        type: "commit",
        data,
        searchMeta: {
          matchType,
          score,
          tier,
          bm25Score: hit.bm25Score,
          annScore: hit.annScore,
          bm25Rank: hit.bm25Rank,
          annRank: hit.annRank,
        },
      })
    }

    // ─── Process PRs (directly from turbopuffer attributes) ───
    const bestByPrId = new Map<string, UnifiedSearchRow>()
    for (const hit of prHits) {
      const prId = hit.doc_id.split(":")[2]
      if (!prId) continue
      const existing = bestByPrId.get(prId)
      if (isBetterHit(hit, existing)) bestByPrId.set(prId, hit)
    }

    for (const [prIdStr, hit] of bestByPrId) {
      const orgRepo = resolveOrgRepo(hit)
      if (!orgRepo) continue
      const prId = parseInt(prIdStr, 10)
      const data: PRResult = {
        id: prIdStr,
        githubPrId: prId,
        number: hit.pr_number ?? 0,
        title: hit.title_text ?? "",
        htmlUrl: hit.pr_html_url ?? null,
        state: hit.pr_state ?? "open",
        draft: false,
        headBranch: normalizeBranch(hit.branch) || null,
        userLogin: hit.author ?? null,
        org: orgRepo[0],
        repo: orgRepo[1],
        createdAt: hit.created_at ?? "",
        mergedAt: hit.pr_merged_at ?? null,
      }
      const { tier, matchType } = assignHitTier(params.q, hit)
      const baseScore = hit.bm25Score ?? hit.annScore ?? 0
      const score = applyRecencyBoost(baseScore, data.createdAt, hit.bm25Score === null)
      results.push({
        type: "pr",
        data,
        searchMeta: {
          matchType,
          score,
          tier,
          bm25Score: hit.bm25Score,
          annScore: hit.annScore,
          bm25Rank: hit.bm25Rank,
          annRank: hit.annRank,
        },
      })
    }

    // ─── Process sessions from turbopuffer attributes (no DB query) ───
    if (wantsSessions && bestByCheckpoint.size > 0) {
      const hydrateStart = Date.now()
      const seenSessionIds = new Set<string>()

      for (const [_cpId, hit] of bestByCheckpoint) {
        const orgRepo = resolveOrgRepo(hit)
        if (!orgRepo) continue

        if (hit.sessions_display) {
          let sessions: unknown
          try {
            sessions = JSON.parse(hit.sessions_display)
          } catch {
            continue
          }
          if (!Array.isArray(sessions)) continue
          for (const s of sessions as Array<{
            id: string
            displayName?: string | null
            prompt: string | null
            createdAt: string | null
            agent: string | null
          }>) {
            if (!s.id || seenSessionIds.has(s.id)) continue
            seenSessionIds.add(s.id)
            const data: SessionResult = {
              sessionId: s.id,
              displayName: s.displayName?.trim() || s.prompt?.trim() || "Untitled session",
              prompt: s.prompt ?? null,
              agent: s.agent ?? null,
              model: null,
              stepCount: 0,
              org: orgRepo[0],
              repo: orgRepo[1],
              branch: normalizeBranch(hit.branch) || null,
              authorUsername: hit.author ?? null,
              createdAt: s.createdAt ?? hit.created_at ?? new Date(0).toISOString(),
            }
            const { tier, matchType } = assignHitTier(params.q, hit)
            const baseScore = hit.bm25Score ?? hit.annScore ?? 0
            const score = applyRecencyBoost(baseScore, data.createdAt, hit.bm25Score === null)
            results.push({
              type: "session",
              data,
              searchMeta: {
                matchType,
                score,
                tier,
                bm25Score: hit.bm25Score,
                annScore: hit.annScore,
                bm25Rank: hit.bm25Rank,
                annRank: hit.annRank,
              },
            })
          }
        }
        // No sessions_display attribute — checkpoint was indexed before this feature.
        // Skip DB fallback; sessions from pre-reindex docs are omitted until full reindex.
      }

      totalSessionHydrationMs = Date.now() - hydrateStart
      console.log(
        `[search] session_hydration`,
        JSON.stringify({
          durationMs: totalSessionHydrationMs,
          checkpointCount: bestByCheckpoint.size,
          sessionCount: seenSessionIds.size,
          source: "turbopuffer",
        }),
      )
    }

    // Funnel diagnostic: per-type, per-tier breakdown
    const funnel = {
      cp: { t0: 0, t1: 0, t2: 0 },
      cm: { t0: 0, t1: 0, t2: 0 },
      pr: { t0: 0, t1: 0, t2: 0 },
      ss: { t0: 0, t1: 0, t2: 0 },
    }
    for (const r of results) {
      const tier = `t${r.searchMeta.tier}` as "t0" | "t1" | "t2"
      if (r.type === "checkpoint") funnel.cp[tier]++
      else if (r.type === "commit") funnel.cm[tier]++
      else if (r.type === "pr") funnel.pr[tier]++
      else if (r.type === "session") funnel.ss[tier]++
    }
    console.log(
      `[search] result_funnel`,
      JSON.stringify({
        total: results.length,
        checkpoints: funnel.cp,
        commits: funnel.cm,
        prs: funnel.pr,
        sessions: funnel.ss,
      }),
    )

    return {
      results,
      fanout_ms: totalFanoutMs,
      session_hydration_ms: totalSessionHydrationMs,
    }
  }

  // rowToCheckpointResult removed — checkpoint results now built directly from turbopuffer attributes

  private async searchRepos(userId: string, params: SearchParams): Promise<SearchResult[]> {
    const rows = await searchReposByUser(this.db, userId, {
      query: params.q,
      repo: params.repo,
      limit: params.perType.repos,
    })

    return rows.map((row: any): SearchResult => {
      const name = row.name ?? ""
      const org = (row.full_name ?? "").split("/")[0] ?? ""
      const exactMatch = name.toLowerCase() === params.q.toLowerCase()
      return {
        type: "repo",
        data: {
          id: row.id,
          githubRepoId: row.github_id,
          org,
          name,
          fullName: row.full_name,
          description: row.description ?? null,
          checkpointCount: row.checkpoint_count ?? 0,
        },
        searchMeta: {
          matchType: "keyword",
          score: exactMatch ? 1.0 : 0.5,
          tier: 0,
        },
      }
    })
  }
}

