func TestSearchModel_BrowseFooterHelp(t *testing.T) {
	t.Parallel()
	m := testModel()

	footer := m.viewHelp()
	wantParts := []string{
		"/ search",
		"↑/↓, j/k scroll",
		"home/end, g/G top/bottom",
		"q quit",
	}
	lastIndex := -1
	for _, want := range wantParts {
		idx := strings.Index(footer, want)
		if idx == -1 {
			t.Fatalf("footer missing %q: %q", want, footer)
		}
		if idx < lastIndex {
