package search

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"
)

const apiTimeout = 30 * time.Second

// DefaultServiceURL is the production search service URL.
const DefaultServiceURL = "https://entire.io"

// WildcardQuery is the query string used when only filters are provided (no search terms).
const WildcardQuery = "*"

// AllReposFilter is the inline repo filter value that disables repo scoping.
const AllReposFilter = "*"

// MaxLimit is the maximum number of results the search API will return per request.
const MaxLimit = 200

// DefaultLimit is the default number of results to fetch per request, matching the UI.
const DefaultLimit = 100

// Meta contains search ranking metadata for a result.
type Meta struct {
	MatchType string   `json:"matchType"`
	Score     float64  `json:"score"`
	Tier      *int     `json:"tier,omitempty"`
	Snippet   string   `json:"snippet,omitempty"`
	Summary   string   `json:"summary,omitempty"`
	BM25Score *float64 `json:"bm25Score,omitempty"`
	ANNScore  *float64 `json:"annScore,omitempty"`
}

// CheckpointResult represents a checkpoint returned by the search service.
type CheckpointResult struct {
	ID             string   `json:"id"`
	Prompt         string   `json:"prompt"`
	CommitMessage  *string  `json:"commitMessage"`
	CommitSubject  *string  `json:"commitSubject"`
	CommitSHA      *string  `json:"commitSha"`
	Branch         string   `json:"branch"`
	Org            string   `json:"org"`
	Repo           string   `json:"repo"`
	Author         string   `json:"author"`
	AuthorUsername *string  `json:"authorUsername"`
	CreatedAt      string   `json:"createdAt"`
	FilesTouched   []string `json:"filesTouched"`
}

// CommitResult represents a commit returned by the search service.
type CommitResult struct {
	ID             string  `json:"id"`
	CommitSHA      string  `json:"commitSha"`
	CommitMessage  string  `json:"commitMessage"`
	CommitSubject  string  `json:"commitSubject"`
	Branch         string  `json:"branch"`
	Org            string  `json:"org"`
	Repo           string  `json:"repo"`
	Author         string  `json:"author"`
	AuthorUsername *string `json:"authorUsername"`
	CreatedAt      string  `json:"createdAt"`
	Additions      int     `json:"additions"`
	Deletions      int     `json:"deletions"`
	FilesChanged   int     `json:"filesChanged"`
	HTMLUrl        *string `json:"htmlUrl"`
}

// SessionResult represents a session returned by the search service.
type SessionResult struct {
	SessionID      string  `json:"sessionId"`
	DisplayName    string  `json:"displayName"`
	Prompt         *string `json:"prompt"`
	Agent          *string `json:"agent"`
	Model          *string `json:"model"`
	StepCount      int     `json:"stepCount"`
	Org            string  `json:"org"`
	Repo           string  `json:"repo"`
	Branch         *string `json:"branch"`
	AuthorUsername *string `json:"authorUsername"`
	CreatedAt      string  `json:"createdAt"`
}

// Result wraps a search result with its type and ranking metadata.
// Exactly one of Checkpoint, Commit, or Session is non-nil based on Type.
type Result struct {
	Type       string            `json:"-"`
	Meta       Meta              `json:"-"`
	Checkpoint *CheckpointResult `json:"-"`
	Commit     *CommitResult     `json:"-"`
	Session    *SessionResult    `json:"-"`

	// rawData preserves the original JSON for unknown types (repo, pr)
	rawData json.RawMessage
}

// resultJSON is the wire format for JSON marshaling/unmarshaling.
type resultJSON struct {
	Type string          `json:"type"`
	Data json.RawMessage `json:"data"`
	Meta Meta            `json:"searchMeta"`
}

// MarshalJSON implements custom JSON marshaling to produce the API wire format.
func (r Result) MarshalJSON() ([]byte, error) {
	var data any
	switch r.Type {
	case "checkpoint":
		data = r.Checkpoint
	case "commit":
		data = r.Commit
	case "session":
		data = r.Session
	default:
		data = r.rawData
	}
	raw, err := json.Marshal(data)
	if err != nil {
		return nil, err
	}
	return json.Marshal(resultJSON{
		Type: r.Type,
		Data: raw,
		Meta: r.Meta,
	})
}

// UnmarshalJSON implements custom JSON unmarshaling to parse typed data.
func (r *Result) UnmarshalJSON(b []byte) error {
	var raw resultJSON
	if err := json.Unmarshal(b, &raw); err != nil {
		return err
	}
	r.Type = raw.Type
	r.Meta = raw.Meta
	r.rawData = raw.Data

	switch raw.Type {
	case "checkpoint":
		var d CheckpointResult
		if err := json.Unmarshal(raw.Data, &d); err != nil {
			return fmt.Errorf("unmarshaling checkpoint data: %w", err)
		}
		r.Checkpoint = &d
	case "commit":
		var d CommitResult
		if err := json.Unmarshal(raw.Data, &d); err != nil {
			return fmt.Errorf("unmarshaling commit data: %w", err)
		}
		r.Commit = &d
	case "session":
		var d SessionResult
		if err := json.Unmarshal(raw.Data, &d); err != nil {
			return fmt.Errorf("unmarshaling session data: %w", err)
		}
		r.Session = &d
	}
	return nil
}

// ResultOrg returns the org for any result type.
func (r Result) ResultOrg() string {
	switch r.Type {
	case "checkpoint":
		if r.Checkpoint != nil {
			return r.Checkpoint.Org
		}
	case "commit":
		if r.Commit != nil {
			return r.Commit.Org
		}
	case "session":
		if r.Session != nil {
			return r.Session.Org
		}
	}
	return ""
}

// ResultRepo returns the repo for any result type.
func (r Result) ResultRepo() string {
	switch r.Type {
	case "checkpoint":
		if r.Checkpoint != nil {
			return r.Checkpoint.Repo
		}
	case "commit":
		if r.Commit != nil {
			return r.Commit.Repo
		}
	case "session":
		if r.Session != nil {
			return r.Session.Repo
		}
	}
	return ""
}

// ResultBranch returns the branch for any result type.
func (r Result) ResultBranch() string {
	switch r.Type {
	case "checkpoint":
		if r.Checkpoint != nil {
			return r.Checkpoint.Branch
		}
	case "commit":
		if r.Commit != nil {
			return r.Commit.Branch
		}
	case "session":
		if r.Session != nil && r.Session.Branch != nil {
			return *r.Session.Branch
		}
	}
	return ""
}

// ResultCreatedAt returns the createdAt for any result type.
func (r Result) ResultCreatedAt() string {
	switch r.Type {
	case "checkpoint":
		if r.Checkpoint != nil {
			return r.Checkpoint.CreatedAt
		}
	case "commit":
		if r.Commit != nil {
			return r.Commit.CreatedAt
		}
	case "session":
		if r.Session != nil {
			return r.Session.CreatedAt
		}
	}
	return ""
}

// ResultAuthor returns the display author for any result type.
func (r Result) ResultAuthor() string {
	switch r.Type {
	case "checkpoint":
		if r.Checkpoint != nil {
			if r.Checkpoint.AuthorUsername != nil && *r.Checkpoint.AuthorUsername != "" {
				return *r.Checkpoint.AuthorUsername
			}
			return r.Checkpoint.Author
		}
	case "commit":
		if r.Commit != nil {
			if r.Commit.AuthorUsername != nil && *r.Commit.AuthorUsername != "" {
				return *r.Commit.AuthorUsername
			}
			return r.Commit.Author
		}
	case "session":
		if r.Session != nil {
			if r.Session.AuthorUsername != nil {
				return *r.Session.AuthorUsername
			}
		}
	}
	return ""
}

// ResultID returns the primary ID for any result type.
func (r Result) ResultID() string {
	switch r.Type {
	case "checkpoint":
		if r.Checkpoint != nil {
			return r.Checkpoint.ID
		}
	case "commit":
		if r.Commit != nil {
			return r.Commit.CommitSHA
		}
	case "session":
		if r.Session != nil {
			return r.Session.SessionID
		}
	}
	return ""
}

// ResultTitle returns the primary display text for any result type.
func (r Result) ResultTitle() string {
	switch r.Type {
	case "checkpoint":
		if r.Checkpoint != nil {
			return r.Checkpoint.Prompt
		}
	case "commit":
		if r.Commit != nil {
			if r.Commit.CommitSubject != "" {
				return r.Commit.CommitSubject
			}
			return r.Commit.CommitMessage
		}
	case "session":
		if r.Session != nil {
			return r.Session.DisplayName
		}
	}
	return ""
}

// TypeCounts holds per-type result counts.
type TypeCounts struct {
	Repos       int `json:"repos"`
	Checkpoints int `json:"checkpoints"`
	Commits     int `json:"commits"`
	PRs         int `json:"prs"`
	Sessions    int `json:"sessions"`
}

// Timing holds search performance timing data.
type Timing struct {
	TotalMs            *float64 `json:"total_ms"`
	KeywordMs          *float64 `json:"keyword_ms"`
	EmbeddingMs        *float64 `json:"embedding_ms"`
	VectorMs           *float64 `json:"vector_ms"`
	RerankMs           *float64 `json:"rerank_ms"`
	FanoutMs           *float64 `json:"fanout_ms"`
	SessionHydrationMs *float64 `json:"session_hydration_ms"`
}

// Response is the search service response.
type Response struct {
	Results  []Result    `json:"results"`
	Total    int         `json:"total"`
	Page     int         `json:"page"`
	Error    string      `json:"error,omitempty"`
	Timing   *Timing     `json:"timing,omitempty"`
	Reranked *bool       `json:"reranked,omitempty"`
	Counts   *TypeCounts `json:"counts,omitempty"`
}

// Config holds the configuration for a search request.
type Config struct {
	ServiceURL  string // Base URL of the search service
	GitHubToken string
	Owner       string
	Repo        string
	Repos       []string
	AllRepos    bool // When true, search all accessible repos (no repo scoping)
	Query       string
	Limit       int
	Author      string // Filter by author name
	Date        string // Filter by time period: "week" or "month"
	Branch      string // Filter by branch name
	Page        int    // 1-based page number (0 means omit, API defaults to 1)
}

// HasFilters reports whether any filter fields are set on the config.
func (c Config) HasFilters() bool {
	return c.Author != "" || c.Date != "" || c.Branch != "" || len(c.Repos) > 0
}

// ParsedInput holds the parsed query and optional filters extracted from search input.
type ParsedInput struct {
	Query  string
	Author string
	Date   string
	Branch string
	Repos  []string
}

// ParseSearchInput extracts filter prefixes from raw input.
// Supports quoted values for single-value filters, for example: author:"alice smith".
// Remaining tokens become the query.
func ParseSearchInput(raw string) ParsedInput {
	var p ParsedInput
	var queryParts []string

	tokens := tokenizeInput(raw)
	for _, tok := range tokens {
		switch {
		case strings.HasPrefix(tok, "author:"):
			p.Author = strings.Trim(tok[len("author:"):], "\"")
		case strings.HasPrefix(tok, "date:"):
			p.Date = strings.Trim(tok[len("date:"):], "\"")
		case strings.HasPrefix(tok, "branch:"):
			p.Branch = strings.Trim(tok[len("branch:"):], "\"")
		case strings.HasPrefix(tok, "repo:"):
			p.Repos = appendUnique(p.Repos, parseListFilter(strings.TrimPrefix(tok, "repo:"))...)
		default:
			queryParts = append(queryParts, tok)
		}
	}

	p.Query = strings.Join(queryParts, " ")
	return p
}

// tokenizeInput splits input on whitespace but respects quoted values after filter prefixes.
// Example: `author:"alice smith" fix bug` → ["author:\"alice smith\"", "fix", "bug"]
func tokenizeInput(s string) []string {
	var tokens []string
	i := 0
	s = strings.TrimSpace(s)
	for i < len(s) {
		// Skip whitespace
		for i < len(s) && s[i] == ' ' {
			i++
		}
		if i >= len(s) {
			break
		}

		start := i

		// Look ahead: is this a prefix:"quoted" token?
		if colonIdx := strings.Index(s[i:], ":\""); colonIdx >= 0 && !strings.Contains(s[i:i+colonIdx], " ") {
			// Found prefix:" — scan to closing quote
			quoteStart := i + colonIdx + 2
			endQuote := strings.IndexByte(s[quoteStart:], '"')
			if endQuote >= 0 {
				i = quoteStart + endQuote + 1
				tokens = append(tokens, s[start:i])
				continue
			}
		}

		// Regular token: advance to next space
		for i < len(s) && s[i] != ' ' {
			i++
		}
		tokens = append(tokens, s[start:i])
	}
	return tokens
}

func parseListFilter(raw string) []string {
	if raw == "" {
		return nil
	}

	parts := strings.Split(raw, ",")
	values := make([]string, 0, len(parts))
	for _, part := range parts {
		value := strings.Trim(strings.TrimSpace(part), "\"")
		if value == "" {
			continue
		}
		values = append(values, value)
	}

	return values
}

// ValidateRepoFilters ensures repo filters match backend semantics.
func ValidateRepoFilters(repos []string) error {
	if len(repos) > 1 {
		return errors.New("only one explicit repo filter is currently supported")
	}
	if len(repos) == 1 && !isValidRepoFilter(repos[0]) {
		return fmt.Errorf(
			"invalid repo filter %q: expected owner/name or *; if you meant all repos, quote the asterisk: --repo '*'",
			repos[0],
		)
	}
	return nil
}

func isValidRepoFilter(repo string) bool {
	if repo == AllReposFilter {
		return true
	}
	if strings.Contains(repo, " ") {
		return false
	}
	parts := strings.Split(repo, "/")
	return len(parts) == 2 && parts[0] != "" && parts[1] != ""
}

func appendUnique(existing []string, values ...string) []string {
	if len(values) == 0 {
		return existing
	}

	seen := make(map[string]struct{}, len(existing)+len(values))
	for _, value := range existing {
		seen[value] = struct{}{}
	}
	for _, value := range values {
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		existing = append(existing, value)
	}

	return existing
}

var httpClient = &http.Client{}

// Search calls the search service to perform a hybrid search.
func Search(ctx context.Context, cfg Config) (*Response, error) {
	ctx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()

	serviceURL := cfg.ServiceURL
	if serviceURL == "" {
		serviceURL = DefaultServiceURL
	}

	u, err := url.Parse(serviceURL)
	if err != nil {
		return nil, fmt.Errorf("parsing service URL: %w", err)
	}
	u.Path = "/search/v1/search"

	q := u.Query()
	q.Set("q", cfg.Query)
	if err := ValidateRepoFilters(cfg.Repos); err != nil {
		return nil, err
	}
	allRepos := cfg.AllRepos || (len(cfg.Repos) == 1 && cfg.Repos[0] == AllReposFilter)
	if len(cfg.Repos) > 0 && !allRepos {
		for _, repo := range cfg.Repos {
			q.Add("repo", repo)
		}
	} else if !allRepos && cfg.Owner != "" && cfg.Repo != "" {
		q.Set("repo", cfg.Owner+"/"+cfg.Repo)
	}
	// Don't set types — let the API return all types (checkpoints, commits, sessions, etc.)
	if cfg.Limit > 0 {
		q.Set("limit", strconv.Itoa(cfg.Limit))
	}
	if cfg.Author != "" {
		q.Set("author", cfg.Author)
	}
	if cfg.Date != "" {
		q.Set("date", cfg.Date)
	}
	if cfg.Branch != "" {
		q.Set("branch", cfg.Branch)
	}
	if cfg.Page > 0 {
		q.Set("page", strconv.Itoa(cfg.Page))
	}
	u.RawQuery = q.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("creating request: %w", err)
	}
	req.Header.Set("Authorization", "Bearer "+cfg.GitHubToken)
	req.Header.Set("User-Agent", "entire-cli")

	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("calling search service: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("reading response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		var errResp struct {
			Error string `json:"error"`
		}
		if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
			return nil, fmt.Errorf("search service error (%d): %s", resp.StatusCode, errResp.Error)
		}
		return nil, fmt.Errorf("search service returned %d: %s", resp.StatusCode, string(body))
	}

	var result Response
	if err := json.Unmarshal(body, &result); err != nil {
		return nil, fmt.Errorf("unexpected response from search service: %s", string(body))
	}

	if result.Error != "" {
		return nil, fmt.Errorf("search service error: %s", result.Error)
	}

	return &result, nil
}

package cli

import (
	"context"
	"fmt"
	"io"
	"strings"
	"time"

	"charm.land/bubbles/v2/key"
	"charm.land/bubbles/v2/textinput"
	"charm.land/bubbles/v2/viewport"
	tea "charm.land/bubbletea/v2"
	glamour "charm.land/glamour/v2"
	"charm.land/glamour/v2/ansi"
	glamourstyles "charm.land/glamour/v2/styles"
	"charm.land/lipgloss/v2"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/cmd/entire/cli/stringutil"
	"github.com/muesli/termenv"
)

// searchMode tracks whether the user is browsing results or editing the search bar.
type searchMode int

const (
	modeBrowse searchMode = iota
	modeSearch
	modeDetail
)

// searchResultsMsg is sent when a search API call completes.
type searchResultsMsg struct {
	results []search.Result
	total   int
	counts  *search.TypeCounts
	err     error
}

// searchMoreResultsMsg is sent when a fetch-more-results call completes.
type searchMoreResultsMsg struct {
	results []search.Result
	err     error
}

// searchStyles holds lipgloss styles specific to the search TUI.
// Styles shared with the status TUI (bold, dim, green, red, cyan, agent/id)
// are accessed via the embedded statusStyles.
type searchStyles struct {
	statusStyles

	sectionTitle lipgloss.Style // bold uppercase section headers
	label        lipgloss.Style // dim key labels in detail panel
	selected     lipgloss.Style // highlighted selected row
	helpKey      lipgloss.Style // colored key hints in footer
	helpSep      lipgloss.Style // dim separator dots in footer
	detailTitle  lipgloss.Style // colored title and section headers (orange, bold)
	detailBorder lipgloss.Style // border style for detail card
	tabActive    lipgloss.Style // active type tab
	tabInactive  lipgloss.Style // inactive type tab
}

// Search palette mirrors activity's dark-mode CSS variables (Tailwind 400-level).
// orange-400 is the primary accent (matches Claude in activity); purple-400 frames
// detail; blue-400 is reserved for links inside markdown snippets.
const (
	searchAccentOrange = "#fb923c" // matches agentDisplayMap["claude"] in activity_render.go
	searchAccentPurple = "#c084fc" // matches agentDisplayMap["kiro"] in activity_render.go
	searchAccentBlue   = "#60a5fa" // matches agentDisplayMap["gemini"] in activity_render.go
)

func newSearchStyles(ss statusStyles) searchStyles {
	s := searchStyles{statusStyles: ss}
	if !ss.colorEnabled {
		return s
	}
	s.sectionTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(searchAccentOrange))
	s.label = lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
	s.selected = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(searchAccentOrange))
	s.helpKey = lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
	s.helpSep = lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
	s.detailTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(searchAccentPurple))
	s.detailBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color(searchAccentPurple)).
		Padding(1, 2)
	s.tabActive = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(searchAccentOrange))
	s.tabInactive = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	return s
}

// helpItem renders a "<key> <desc>" pair for a TUI help footer using the
// shared helpKey style. keyLabel may come from a key.Binding's Help().Key or
// be a composite literal like "j/k".
func (s searchStyles) helpItem(keyLabel, desc string) string {
	return s.render(s.helpKey, keyLabel) + " " + desc
}

const resultsPerPage = 25

// typeFilter represents the active type tab in the TUI.
type typeFilter string

const (
	typeFilterAll         typeFilter = ""
	typeFilterCheckpoints typeFilter = "checkpoint"
	typeFilterCommits     typeFilter = "commit"
	typeFilterSessions    typeFilter = "session"
)

// searchModel is the bubbletea model for interactive search results.
type searchModel struct {
	results      []search.Result
	cursor       int
	page         int // 0-based display page index
	total        int
	width        int
	height       int
	mode         searchMode
	loading      bool
	fetchingMore bool // true while fetching next API page
	searchErr    string
	input        textinput.Model
	searchCfg    search.Config
	apiPage      int // 1-based last-fetched API page
	styles       searchStyles
	detailVP     viewport.Model     // full-screen detail view
	browseVP     viewport.Model     // scrollable browse view
	filterType   typeFilter         // active type tab filter
	counts       *search.TypeCounts // per-type counts from API

	// darkBg is captured once before bubbletea takes over the terminal so the
	// snippet renderer never re-queries the terminal via OSC during the Update
	// loop (which would race against bubbletea's stdin reader and stall).
	darkBg bool
}

// filteredResults returns results matching the active type filter.
func (m searchModel) filteredResults() []search.Result {
	if m.filterType == typeFilterAll {
		return m.results
	}
	var out []search.Result
	for _, r := range m.results {
		if typeFilter(r.Type) == m.filterType {
			out = append(out, r)
		}
	}
	return out
}

// pageResults returns the slice of results for the current page.
func (m searchModel) pageResults() []search.Result {
	filtered := m.filteredResults()
	start := m.page * resultsPerPage
	if start >= len(filtered) {
		return nil
	}
	end := start + resultsPerPage
	if end > len(filtered) {
		end = len(filtered)
	}
	return filtered[start:end]
}

// totalPages returns the number of pages based on the filtered result count.
func (m searchModel) totalPages() int {
	n := len(m.filteredResults())
	if n == 0 {
		return 1
	}
	return (n + resultsPerPage - 1) / resultsPerPage
}

// selectedResult returns the currently selected result, accounting for pagination.
func (m searchModel) selectedResult() *search.Result {
	pageResults := m.pageResults()
	if m.cursor >= 0 && m.cursor < len(pageResults) {
		return &pageResults[m.cursor]
	}
	return nil
}

// computeTypeCounts calculates per-type counts from the loaded results,
// falling back to API-provided counts when available.
func (m searchModel) computeTypeCounts() (checkpoints, commits, sessions int) {
	if m.counts != nil {
		return m.counts.Checkpoints, m.counts.Commits, m.counts.Sessions
	}
	for _, r := range m.results {
		switch r.Type {
		case "checkpoint":
			checkpoints++
		case "commit":
			commits++
		case "session":
			sessions++
		}
	}
	return
}

func newSearchModel(results []search.Result, query string, total int, cfg search.Config, ss statusStyles) searchModel {
	styles := newSearchStyles(ss)

	ti := textinput.New()
	ti.SetValue(query)
	ti.Prompt = " › "
	ti.Placeholder = "search checkpoints... (author:name date:week branch:main repo:owner/name or repo:*)"
	ti.CharLimit = 200
	ti.SetWidth(max(ss.width-6, 30))
	ti.SetVirtualCursor(true)
	if ss.colorEnabled {
		s := ti.Styles()
		focused := s.Focused
		focused.Prompt = lipgloss.NewStyle().Foreground(lipgloss.Color(searchAccentOrange)).Bold(true)
		focused.Text = lipgloss.NewStyle()
		focused.Placeholder = lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
		s.Focused = focused
		s.Cursor.Color = lipgloss.Color(searchAccentOrange)
		ti.SetStyles(s)
	}

	var apiPage int
	if results != nil {
		apiPage = 1
	}

	m := searchModel{
		results:   results,
		total:     total,
		width:     ss.width,
		mode:      modeBrowse,
		input:     ti,
		searchCfg: cfg,
		apiPage:   apiPage,
		styles:    styles,
		browseVP:  viewport.New(viewport.WithWidth(ss.width), viewport.WithHeight(1)), // height set on first WindowSizeMsg
		darkBg:    termenv.HasDarkBackground(),
	}
	m = m.refreshBrowseContent()
	return m
}

func (m searchModel) Init() tea.Cmd {
	if m.mode == modeSearch {
		return textinput.Blink
	}
	return nil
}

func (m searchModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:cyclop // bubbletea interface
	switch msg := msg.(type) {
	case searchResultsMsg:
		m.loading = false
		m.fetchingMore = false
		if msg.err != nil {
			m.searchErr = msg.err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.searchErr = ""
		m.results = msg.results
		m.total = msg.total
		m.counts = msg.counts
		m.apiPage = 1
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil

	case searchMoreResultsMsg:
		m.fetchingMore = false
		if msg.err != nil {
			m.searchErr = msg.err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.apiPage++
		if len(msg.results) > 0 {
			m.results = append(m.results, msg.results...)
		} else {
			// API returned no more results — cap total to what we have
			m.total = len(m.results)
		}
		m = m.refreshBrowseContent()
		return m, nil

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.input.SetWidth(max(msg.Width-6, 30))
		m.browseVP.SetWidth(msg.Width)
		m.browseVP.SetHeight(max(msg.Height-1, 1)) // reserve 1 line for footer
		if m.mode == modeDetail {
			m.detailVP.SetWidth(msg.Width)
			m.detailVP.SetHeight(max(msg.Height-2, 1))
		}
		m = m.refreshBrowseContent()
		return m, nil

	case tea.KeyPressMsg:
		switch m.mode {
		case modeSearch:
			return m.updateSearchMode(msg)
		case modeDetail:
			return m.updateDetailMode(msg)
		case modeBrowse:
			return m.updateBrowseMode(msg)
		}
	}
	return m, nil
}

func (m searchModel) updateSearchMode(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch {
	case key.Matches(msg, keys.Back):
		m.mode = modeBrowse
		m.input.Blur()
		m = m.refreshBrowseContent()
		return m, nil
	case key.Matches(msg, keys.Confirm):
		raw := strings.TrimSpace(m.input.Value())
		if raw == "" {
			return m, nil
		}
		parsed := search.ParseSearchInput(raw)
		if err := search.ValidateRepoFilters(parsed.Repos); err != nil {
			m.searchErr = err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.mode = modeBrowse
		m.input.Blur()
		m.loading = true
		m.searchErr = ""
		cfg := m.searchCfg
		cfg.Query = parsed.Query
		if cfg.Query == "" {
			cfg.Query = search.WildcardQuery
		}
		cfg.Author = parsed.Author
		cfg.Date = parsed.Date
		cfg.Branch = parsed.Branch
		cfg.Repos = parsed.Repos
		m.searchCfg = cfg
		m = m.refreshBrowseContent()
		return m, performSearch(cfg)
	}

	var cmd tea.Cmd
	m.input, cmd = m.input.Update(msg)
	return m, cmd
}

func (m searchModel) updateBrowseMode(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	// Type tab keys (1/2/3)
	switch msg.String() {
	case "1":
		m.filterType = typeFilterCheckpoints
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil
	case "2":
		m.filterType = typeFilterSessions
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil
	case "3":
		m.filterType = typeFilterCommits
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil
	case "0":
		m.filterType = typeFilterAll
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil
	}

	pageLen := len(m.pageResults())
	switch {
	case key.Matches(msg, keys.Quit), key.Matches(msg, keys.Back), msg.String() == "h":
		return m, tea.Quit
	case key.Matches(msg, keys.Up):
		if m.cursor > 0 {
			m.cursor--
			m = m.refreshBrowseContent()
		}
	case key.Matches(msg, keys.Down):
		if m.cursor < pageLen-1 {
			m.cursor++
			m = m.refreshBrowseContent()
		}
	case key.Matches(msg, keys.Home):
		m.page = 0
		m.cursor = 0
		m = m.refreshBrowseContent()
		m.browseVP.GotoTop()
	case key.Matches(msg, keys.End):
		filtered := m.filteredResults()
		if len(filtered) > 0 {
			lastLoaded := len(filtered) - 1
			m.page = min(lastLoaded/resultsPerPage, m.totalPages()-1)
			if pageLen := len(m.pageResults()); pageLen > 0 {
				m.cursor = pageLen - 1
			}
			m = m.refreshBrowseContent()
			m.browseVP.GotoBottom()
		}
	case key.Matches(msg, keys.NextPage):
		if m.page < m.totalPages()-1 {
			m.page++
			m.cursor = 0
			m.browseVP.GotoTop()
			// Fetch next API page if we've scrolled past loaded results
			start := m.page * resultsPerPage
			if start >= len(m.filteredResults()) && !m.fetchingMore {
				m.fetchingMore = true
				m = m.refreshBrowseContent()
				return m, fetchMoreResults(m.searchCfg, m.apiPage+1)
			}
			m = m.refreshBrowseContent()
		}
	case key.Matches(msg, keys.PrevPage):
		if m.page > 0 {
			m.page--
			m.cursor = 0
			m.browseVP.GotoTop()
			m = m.refreshBrowseContent()
		}
	case key.Matches(msg, keys.Confirm):
		if r := m.selectedResult(); r != nil {
			m.mode = modeDetail
			content := m.renderDetailContent(*r, m.width, true)
			m.detailVP = viewport.New(viewport.WithWidth(m.width), viewport.WithHeight(max(m.height-2, 1)))
			m.detailVP.SetContent(content)
			return m, nil
		}
	case key.Matches(msg, keys.Search):
		m.mode = modeSearch
		m.input.Focus()
		return m, textinput.Blink
	default:
		// Forward unhandled keys (pgup/pgdn/ctrl+u/ctrl+d/g/G/etc.) to viewport for scrolling
		var cmd tea.Cmd
		m.browseVP, cmd = m.browseVP.Update(msg)
		return m, cmd
	}
	return m, nil
}

func (m searchModel) updateDetailMode(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch {
	case key.Matches(msg, keys.Quit):
		return m, tea.Quit
	case key.Matches(msg, keys.Back), msg.String() == "backspace":
		m.mode = modeBrowse
		return m, nil
	case key.Matches(msg, keys.Search):
		m.mode = modeSearch
		m.input.Focus()
		return m, textinput.Blink
	}
	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func performSearch(cfg search.Config) tea.Cmd {
	return func() tea.Msg {
		resp, err := search.Search(context.Background(), cfg)
		if err != nil {
			return searchResultsMsg{err: err}
		}
		return searchResultsMsg{results: resp.Results, total: resp.Total, counts: resp.Counts}
	}
}

func fetchMoreResults(cfg search.Config, page int) tea.Cmd {
	return func() tea.Msg {
		cfg.Page = page
		resp, err := search.Search(context.Background(), cfg)
		if err != nil {
			return searchMoreResultsMsg{err: err}
		}
		return searchMoreResultsMsg{results: resp.Results}
	}
}

// ─── View ────────────────────────────────────────────────────────────────────

func (m searchModel) View() tea.View {
	v := tea.View{AltScreen: true}
	if m.width == 0 {
		return v
	}

	switch m.mode {
	case modeDetail:
		v.SetContent(m.viewDetailFull())
	case modeSearch:
		v.SetContent(m.viewSearchMode())
	case modeBrowse:
		v.SetContent(m.browseVP.View() + "\n" + m.viewHelp())
	}
	return v
}

func (m searchModel) viewSearchHeader(b *strings.Builder) {
	pad := " "
	b.WriteString("\n")
	b.WriteString(pad + m.styles.render(m.styles.sectionTitle, "SEARCH"))
	b.WriteString("\n\n")
}

func (m searchModel) viewSearchMode() string {
	var b strings.Builder
	m.viewSearchHeader(&b)
	b.WriteString(" " + m.input.View())
	b.WriteString("\n\n")
	if m.searchErr != "" {
		b.WriteString(" " + m.styles.render(m.styles.red, "Error: "+m.searchErr))
		b.WriteString("\n\n")
	}
	b.WriteString(" " + m.styles.render(m.styles.dim, "  Filters: author:<name>  date:<week|month>  branch:<name>  repo:<owner/name|*>"))
	b.WriteString("\n")
	b.WriteString(" " + m.styles.render(m.styles.dim, "  repo:* searches all accessible repos"))
	b.WriteString("\n\n")
	b.WriteString(m.viewHelp())
	return b.String()
}

// viewTypeTabs renders the type filter tabs with counts.
func (m searchModel) viewTypeTabs() string {
	cpCount, cmCount, ssCount := m.computeTypeCounts()
	allCount := cpCount + cmCount + ssCount

	renderTab := func(label string, filter typeFilter, count int, keyHint string) string {
		text := fmt.Sprintf("[%s] %s %d", keyHint, label, count)
		if m.filterType == filter {
			return m.styles.render(m.styles.tabActive, text)
		}
		return m.styles.render(m.styles.tabInactive, text)
	}

	tabs := []string{
		renderTab("All", typeFilterAll, allCount, "0"),
		renderTab("Checkpoints", typeFilterCheckpoints, cpCount, "1"),
		renderTab("Sessions", typeFilterSessions, ssCount, "2"),
		renderTab("Commits", typeFilterCommits, cmCount, "3"),
	}

	return strings.Join(tabs, "  ")
}

// renderBrowseContent builds the scrollable content for browse mode (everything except the footer).
func (m searchModel) renderBrowseContent() string {
	var b strings.Builder
	pad := " "

	m.viewSearchHeader(&b)

	query := m.input.Value()
	b.WriteString(pad + m.styles.render(m.styles.sectionTitle, "›") + " " + m.styles.render(m.styles.bold, query))
	b.WriteString("\n\n")

	// Loading / error / empty states
	if m.loading {
		b.WriteString(pad + m.styles.render(m.styles.dim, "Searching..."))
		return b.String()
	}
	if m.searchErr != "" {
		b.WriteString(pad + m.styles.render(m.styles.red, "Error: "+m.searchErr))
		return b.String()
	}
	if len(m.results) == 0 {
		b.WriteString(pad + m.styles.render(m.styles.dim, "No results found."))
		return b.String()
	}

	// Type tabs
	b.WriteString(pad + m.viewTypeTabs())
	b.WriteString("\n\n")

	// Section: RESULTS
	b.WriteString(pad + m.styles.render(m.styles.sectionTitle, "RESULTS"))
	b.WriteString("\n\n")

	// Table (current page only)
	filtered := m.filteredResults()
	if len(filtered) == 0 {
		b.WriteString(pad + m.styles.render(m.styles.dim, "No results for this type."))
		return b.String()
	}
	if m.fetchingMore && m.pageResults() == nil {
		b.WriteString(pad + m.styles.render(m.styles.dim, "Loading more results...") + "\n")
	} else {
		b.WriteString(m.viewTable())
	}
	b.WriteString("\n")

	// Detail card (no truncation — viewport handles overflow)
	if r := m.selectedResult(); r != nil {
		b.WriteString(m.viewDetailCard(*r))
	}

	return strings.TrimRight(b.String(), "\n")
}

// refreshBrowseContent rebuilds the browse viewport content from current state.
func (m searchModel) refreshBrowseContent() searchModel {
	m.browseVP.SetContent(m.renderBrowseContent())
	return m
}

func (m searchModel) viewTable() string {
	contentWidth := max(m.width-2, 0) // 1 char padding each side
	cols := computeColumns(contentWidth)
	pad := " "

	var b strings.Builder

	// Column headers
	hdr := fmt.Sprintf("%-*s %-*s %-*s %-*s %-*s %-*s %-*s",
		cols.typeCol, "Type",
		cols.age, "Age",
		cols.id, "ID",
		cols.branch, "Branch",
		cols.repo, "Repo",
		cols.prompt, "Title",
		cols.author, "Author",
	)
	b.WriteString(pad + m.styles.render(m.styles.dim, hdr) + "\n")

	// Header separator
	b.WriteString(pad + m.styles.render(m.styles.dim, strings.Repeat("─", contentWidth)) + "\n")

	// Rows
	for i, r := range m.pageResults() {
		row := m.viewRow(r, cols)
		if i == m.cursor && m.styles.colorEnabled {
			b.WriteString(pad + m.styles.selected.Render(row))
		} else {
			b.WriteString(pad + row)
		}
		b.WriteString("\n")
	}

	return b.String()
}

// typeLabel returns a short type badge for display in the table.
func typeLabel(resultType string) string {
	switch resultType {
	case "checkpoint":
		return "CP"
	case "commit":
		return "CM"
	case "session":
		return "SS"
	default:
		return strings.ToUpper(resultType[:min(2, len(resultType))])
	}
}

func (m searchModel) viewRow(r search.Result, cols columnLayout) string {
	typeBadge := fmt.Sprintf("%-*s", cols.typeCol, typeLabel(r.Type))
	age := fmt.Sprintf("%-*s", cols.age, stringutil.TruncateRunes(formatSearchAge(r.ResultCreatedAt()), cols.age, ""))
	id := fmt.Sprintf("%-*s", cols.id, stringutil.TruncateRunes(formatResultID(r), cols.id-1, "…"))
	branch := fmt.Sprintf("%-*s", cols.branch, stringutil.TruncateRunes(r.ResultBranch(), cols.branch-1, "…"))
	repo := fmt.Sprintf("%-*s", cols.repo, stringutil.TruncateRunes(
		r.ResultOrg()+"/"+r.ResultRepo(), cols.repo-1, "…",
	))
	title := fmt.Sprintf("%-*s", cols.prompt, stringutil.TruncateRunes(
		stringutil.CollapseWhitespace(r.ResultTitle()), cols.prompt-1, "…",
	))
	author := fmt.Sprintf("%-*s", cols.author, stringutil.TruncateRunes(r.ResultAuthor(), cols.author-1, "…"))

	return fmt.Sprintf("%s %s %s %s %s %s %s", typeBadge, age, id, branch, repo, title, author)
}

// formatResultID returns a display-friendly ID for a result.
func formatResultID(r search.Result) string {
	switch r.Type {
	case "commit":
		if r.Commit != nil && len(r.Commit.CommitSHA) > 7 {
			return r.Commit.CommitSHA[:7]
		}
	}
	return r.ResultID()
}

// renderDetailContent builds the text content for a result detail (no border/card chrome).
func (m searchModel) renderDetailContent(r search.Result, contentWidth int, showSections bool) string {
	switch r.Type {
	case "checkpoint":
		return m.renderCheckpointDetail(r, contentWidth, showSections)
	case "commit":
		return m.renderCommitDetail(r, contentWidth, showSections)
