package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	tea "charm.land/bubbletea/v2"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/spf13/cobra"
)

func newSearchCmd() *cobra.Command {
	var (
		jsonOutput       bool
		limitFlag        int
		pageFlag         int
		authorFlag       string
		dateFlag         string
		branchFlag       string
		repoFlag         string
		allReposFlag     bool
		insecureHTTPAuth bool
	)

	cmd := &cobra.Command{
		Use:   "search [query]",
		Short: "Search checkpoints, commits, and sessions using semantic and keyword matching",
		Long: `Search checkpoints, commits, and sessions using hybrid search (semantic + keyword),
powered by the Entire search service.

Requires authentication via 'entire login' (GitHub device flow).

By default, results are scoped to the current repository. Use --all-repos to
search across all accessible repos.

Run without arguments to open an interactive search. Results are
displayed in an interactive table. Use --json for machine-readable output.

CLI queries also support inline filters like author:<name>, date:<week|month>,
branch:<name>, repo:<owner/name>, and repo:* to search all accessible repos.`,
		Args:   cobra.ArbitraryArgs,
		Hidden: true,
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			query := strings.Join(args, " ")

			// Extract inline filters (author:, date:, branch:, repo:) from query args
			parsed := search.ParseSearchInput(query)
			query = parsed.Query
			if authorFlag == "" {
				authorFlag = parsed.Author
			}
			if dateFlag == "" {
				dateFlag = parsed.Date
			}
			if branchFlag == "" {
				branchFlag = parsed.Branch
			}
			repos := parsed.Repos
			if repoFlag != "" {
				repos = []string{repoFlag}
			}
			if err := search.ValidateRepoFilters(repos); err != nil {
				return fmt.Errorf("validating repo filter: %w", err)
			}

			// Check for repo:* in inline filters
			allRepos := allReposFlag
			if len(repos) == 1 && repos[0] == search.AllReposFilter {
				allRepos = true
			}

			w := cmd.OutOrStdout()
			isTerminal := interactive.IsTerminalWriter(w)
			hasFilters := authorFlag != "" || dateFlag != "" || branchFlag != "" || len(repos) > 0

			// Fast-fail: no query + non-interactive mode = error (before auth/git checks)
			if query == "" && !hasFilters && (jsonOutput || !isTerminal || IsAccessibleMode()) {
				return errors.New("query required when using --json, accessible mode, or piped output. Usage: entire search <query>")
			}

			// Get the repo's GitHub remote URL
			repo, err := strategy.OpenRepository(ctx)
			if err != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run this command from within a git repository.")
				return NewSilentError(err)
			}
			defer repo.Close()

			remote, err := repo.Remote("origin")
			if err != nil {
				return fmt.Errorf("could not find 'origin' remote: %w", err)
			}
			urls := remote.Config().URLs
			if len(urls) == 0 {
				return errors.New("origin remote has no URLs configured")
			}

			owner, repoName, err := search.ParseGitHubRemote(urls[0])
			if err != nil {
				return fmt.Errorf("parsing remote URL: %w", err)
			}

			serviceURL := os.Getenv("ENTIRE_SEARCH_URL")
			if serviceURL == "" {
				// Search lives on the data API host. Fall back to
				// api.BaseURL() so ENTIRE_API_BASE_URL applies; the search
				// package's DefaultServiceURL is only consulted by callers
				// that bypass this entry point.
				serviceURL = api.BaseURL()
			}

			ghToken, err := resolveSearchToken(ctx, serviceURL, insecureHTTPAuth)
			if err != nil {
				return err
			}

			searchCfg := search.Config{
				ServiceURL:  serviceURL,
				GitHubToken: ghToken,
				Owner:       owner,
				Repo:        repoName,
				Repos:       repos,
				AllRepos:    allRepos,
				Query:       query,
				Limit:       limitFlag,
				Page:        pageFlag,
				Author:      authorFlag,
				Date:        dateFlag,
				Branch:      branchFlag,
			}

			// Use wildcard query when only filters are provided
			if query == "" && searchCfg.HasFilters() {
				searchCfg.Query = search.WildcardQuery
			}

			// No query provided + interactive = open TUI with search bar focused
			if query == "" && !searchCfg.HasFilters() {
				searchCfg.Limit = search.DefaultLimit
				styles := newStatusStyles(w)
				model := newSearchModel(nil, "", 0, searchCfg, styles)
				model.mode = modeSearch
				model.input.Focus()
				p := tea.NewProgram(model)
				if _, err := p.Run(); err != nil {
					return fmt.Errorf("TUI error: %w", err)
				}
				return nil
			}

			// Fetch max results so client-side pagination works.
			// The search API caps results at the limit, so we fetch
			// the maximum and paginate client-side for all output modes.
			requestedLimit := searchCfg.Limit
			requestedPage := searchCfg.Page
			searchCfg.Limit = search.DefaultLimit
			searchCfg.Page = 0 // let API default to page 1

			resp, err := search.Search(ctx, searchCfg)
			if err != nil {
				return fmt.Errorf("search failed: %w", err)
			}

			// JSON output: explicit flag or piped/redirected stdout
			if jsonOutput || !isTerminal {
				return writeSearchJSON(w, resp, requestedLimit, requestedPage)
			}

			styles := newStatusStyles(w)

			// Accessible mode: static table
			if IsAccessibleMode() {
				if len(resp.Results) == 0 {
					fmt.Fprintln(w, "No results found.")
					return nil
				}
				renderSearchStatic(w, resp.Results, query, resp.Total, styles)
				return nil
			}

			// Interactive TUI
			model := newSearchModel(resp.Results, query, resp.Total, searchCfg, styles)
			p := tea.NewProgram(model)
			if _, err := p.Run(); err != nil {
				return fmt.Errorf("TUI error: %w", err)
			}
			return nil
		},
	}

	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
	cmd.Flags().IntVar(&limitFlag, "limit", resultsPerPage, "Maximum number of results per page")
	cmd.Flags().IntVar(&pageFlag, "page", 1, "Page number (1-based)")
	cmd.Flags().StringVar(&authorFlag, "author", "", "Filter by author name")
	cmd.Flags().StringVar(&dateFlag, "date", "", "Filter by time period (week or month)")
	cmd.Flags().StringVar(&branchFlag, "branch", "", "Filter by branch name")
	cmd.Flags().StringVar(&repoFlag, "repo", "", "Filter by repository (owner/name or *)")
	cmd.Flags().BoolVar(&allReposFlag, "all-repos", false, "Search all accessible repos instead of just the current one")
	addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)

	cmd.RegisterFlagCompletionFunc("date", func(*cobra.Command, []string, string) ([]string, cobra.ShellCompDirective) { //nolint:errcheck,gosec // only fails if the flag isn't defined; defined directly above
		return []string{"week", "month"}, cobra.ShellCompDirectiveNoFileComp
	})
	cmd.RegisterFlagCompletionFunc("repo", completeRepoFlag) //nolint:errcheck,gosec // only fails if the flag isn't defined; defined directly above

	return cmd
}

// resolveSearchToken returns a bearer scoped to the search service host.
// In split-host deployments this triggers an RFC 8693 exchange so the bearer
// carries the data-API audience rather than the auth-host one; single-host
// setups hit the same-host shortcut and return the core token unchanged.
// insecureHTTPAuth opts into non-loopback http:// resources at the
// tokenmanager layer, matching the per-command --insecure-http-auth pattern
// used by NewAuthenticatedAPIClient and newRecapClient.
func resolveSearchToken(ctx context.Context, serviceURL string, insecureHTTPAuth bool) (string, error) {
	if insecureHTTPAuth {
		auth.EnableInsecureHTTP()
	}
	token, err := auth.ResolveDataAPIToken(ctx, serviceURL)
	if errors.Is(err, auth.ErrNotLoggedIn) {
		return "", errors.New("not authenticated. Run 'entire login' to authenticate")
	}
	if err != nil {
		return "", fmt.Errorf("reading credentials: %w", err)
	}
	return token, nil
}

// completeRepoFlag returns shell-completion suggestions for the search
// command's --repo flag. "*" is always offered so the wildcard works
// regardless of auth state. Errors are swallowed (rather than surfaced via
// ShellCompDirectiveError) because completion runs on every TAB press and
// must never pollute the user's prompt with error output.
func completeRepoFlag(cmd *cobra.Command, _ []string, _ string) ([]string, cobra.ShellCompDirective) {
	suggestions := []string{"*"}
	client, err := NewAuthenticatedAPIClient(cmd.Context(), false)
	if err != nil {
		return suggestions, cobra.ShellCompDirectiveNoFileComp
	}
	repos, err := client.ListRepositories(cmd.Context(), api.RepositorySortRecent)
	if err != nil {
		return suggestions, cobra.ShellCompDirectiveNoFileComp
	}
	for _, r := range repos {
		if r.CheckpointCount == 0 {
			continue // searching a repo with no checkpoints would always be empty
		}
		suggestions = append(suggestions, r.FullName)
	}
	return suggestions, cobra.ShellCompDirectiveNoFileComp
}

// writeSearchJSON writes client-side paginated search results as JSON.
func writeSearchJSON(w io.Writer, resp *search.Response, limit, page int) error {
	if limit <= 0 {
		limit = resultsPerPage
	}

	total := len(resp.Results)
	totalPages := (total + limit - 1) / limit
	if totalPages < 1 {
		totalPages = 1
	}
	if page < 1 {
		page = 1
	}

	// Slice results for the requested page.
	start := (page - 1) * limit
	end := start + limit
	var pageResults []search.Result
	if start < total {
		if end > total {
			end = total
		}
		pageResults = resp.Results[start:end]
	}
	if pageResults == nil {
		pageResults = []search.Result{}
	}

	out := struct {
		Results    []search.Result    `json:"results"`
		Total      int                `json:"total"`
		Page       int                `json:"page"`
		TotalPages int                `json:"total_pages"`
		Limit      int                `json:"limit"`
		Counts     *search.TypeCounts `json:"counts,omitempty"`
	}{
		Results:    pageResults,
		Total:      total,
		Page:       page,
		TotalPages: totalPages,
		Limit:      limit,
		Counts:     resp.Counts,
	}
	data, err := jsonutil.MarshalIndentWithNewline(out, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling results: %w", err)
	}
	fmt.Fprint(w, string(data))
	return nil
}

package cli

import (
	"context"
	"fmt"
	"io"
	"strings"
	"time"

	"charm.land/bubbles/v2/key"
	"charm.land/bubbles/v2/textinput"
	"charm.land/bubbles/v2/viewport"
	tea "charm.land/bubbletea/v2"
	glamour "charm.land/glamour/v2"
	"charm.land/glamour/v2/ansi"
	glamourstyles "charm.land/glamour/v2/styles"
	"charm.land/lipgloss/v2"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/cmd/entire/cli/stringutil"
	"github.com/muesli/termenv"
)

// searchMode tracks whether the user is browsing results or editing the search bar.
type searchMode int

const (
	modeBrowse searchMode = iota
	modeSearch
	modeDetail
)

// searchResultsMsg is sent when a search API call completes.
type searchResultsMsg struct {
	results []search.Result
	total   int
	counts  *search.TypeCounts
	err     error
}

// searchMoreResultsMsg is sent when a fetch-more-results call completes.
type searchMoreResultsMsg struct {
	results []search.Result
	err     error
}

// searchStyles holds lipgloss styles specific to the search TUI.
// Styles shared with the status TUI (bold, dim, green, red, cyan, agent/id)
// are accessed via the embedded statusStyles.
type searchStyles struct {
	statusStyles

	sectionTitle lipgloss.Style // bold uppercase section headers
	label        lipgloss.Style // dim key labels in detail panel
	selected     lipgloss.Style // highlighted selected row
	helpKey      lipgloss.Style // colored key hints in footer
	helpSep      lipgloss.Style // dim separator dots in footer
	detailTitle  lipgloss.Style // colored title and section headers (orange, bold)
	detailBorder lipgloss.Style // border style for detail card
	tabActive    lipgloss.Style // active type tab
	tabInactive  lipgloss.Style // inactive type tab
}

// Search palette mirrors activity's dark-mode CSS variables (Tailwind 400-level).
// orange-400 is the primary accent (matches Claude in activity); purple-400 frames
// detail; blue-400 is reserved for links inside markdown snippets.
const (
	searchAccentOrange = "#fb923c" // matches agentDisplayMap["claude"] in activity_render.go
	searchAccentPurple = "#c084fc" // matches agentDisplayMap["kiro"] in activity_render.go
	searchAccentBlue   = "#60a5fa" // matches agentDisplayMap["gemini"] in activity_render.go
)

func newSearchStyles(ss statusStyles) searchStyles {
	s := searchStyles{statusStyles: ss}
	if !ss.colorEnabled {
		return s
	}
	s.sectionTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(searchAccentOrange))
	s.label = lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
	s.selected = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(searchAccentOrange))
	s.helpKey = lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
	s.helpSep = lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
	s.detailTitle = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(searchAccentPurple))
	s.detailBorder = lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color(searchAccentPurple)).
		Padding(1, 2)
	s.tabActive = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color(searchAccentOrange))
	s.tabInactive = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	return s
}

// helpItem renders a "<key> <desc>" pair for a TUI help footer using the
// shared helpKey style. keyLabel may come from a key.Binding's Help().Key or
// be a composite literal like "j/k".
func (s searchStyles) helpItem(keyLabel, desc string) string {
	return s.render(s.helpKey, keyLabel) + " " + desc
}

const resultsPerPage = 25

// typeFilter represents the active type tab in the TUI.
type typeFilter string

const (
	typeFilterAll         typeFilter = ""
	typeFilterCheckpoints typeFilter = typeFilter(search.TypeCheckpoint)
	typeFilterCommits     typeFilter = typeFilter(search.TypeCommit)
	typeFilterSessions    typeFilter = typeFilter(search.TypeSession)
)

// searchModel is the bubbletea model for interactive search results.
type searchModel struct {
	results      []search.Result
	cursor       int
	page         int // 0-based display page index
	total        int
	width        int
	height       int
	mode         searchMode
	loading      bool
	fetchingMore bool // true while fetching next API page
	searchErr    string
	input        textinput.Model
	searchCfg    search.Config
	apiPage      int // 1-based last-fetched API page
	styles       searchStyles
	detailVP     viewport.Model     // full-screen detail view
	browseVP     viewport.Model     // scrollable browse view
	filterType   typeFilter         // active type tab filter
	counts       *search.TypeCounts // per-type counts from API

	// darkBg is captured once before bubbletea takes over the terminal so the
	// snippet renderer never re-queries the terminal via OSC during the Update
	// loop (which would race against bubbletea's stdin reader and stall).
	darkBg bool
}

// filteredResults returns results matching the active type filter.
func (m searchModel) filteredResults() []search.Result {
	if m.filterType == typeFilterAll {
		return m.results
	}
	var out []search.Result
	for _, r := range m.results {
		if typeFilter(r.Type) == m.filterType {
			out = append(out, r)
		}
	}
	return out
}

// pageResults returns the slice of results for the current page.
func (m searchModel) pageResults() []search.Result {
	filtered := m.filteredResults()
	start := m.page * resultsPerPage
	if start >= len(filtered) {
		return nil
	}
	end := start + resultsPerPage
	if end > len(filtered) {
		end = len(filtered)
	}
	return filtered[start:end]
}

// totalPages returns the number of pages based on the filtered result count.
func (m searchModel) totalPages() int {
	n := len(m.filteredResults())
	if n == 0 {
		return 1
	}
	return (n + resultsPerPage - 1) / resultsPerPage
}

// selectedResult returns the currently selected result, accounting for pagination.
func (m searchModel) selectedResult() *search.Result {
	pageResults := m.pageResults()
	if m.cursor >= 0 && m.cursor < len(pageResults) {
		return &pageResults[m.cursor]
	}
	return nil
}

// computeTypeCounts calculates per-type counts from the loaded results,
// falling back to API-provided counts when available.
func (m searchModel) computeTypeCounts() (checkpoints, commits, sessions int) {
	if m.counts != nil {
		return m.counts.Checkpoints, m.counts.Commits, m.counts.Sessions
	}
	for _, r := range m.results {
		switch typeFilter(r.Type) {
		case typeFilterCheckpoints:
			checkpoints++
		case typeFilterCommits:
			commits++
		case typeFilterSessions:
			sessions++
		}
	}
	return
}

func newSearchModel(results []search.Result, query string, total int, cfg search.Config, ss statusStyles) searchModel {
	styles := newSearchStyles(ss)

	ti := textinput.New()
	ti.SetValue(query)
	ti.Prompt = " › "
	ti.Placeholder = "search checkpoints... (author:name date:week branch:main repo:owner/name or repo:*)"
	ti.CharLimit = 200
	ti.SetWidth(max(ss.width-6, 30))
	ti.SetVirtualCursor(true)
	if ss.colorEnabled {
		s := ti.Styles()
		focused := s.Focused
		focused.Prompt = lipgloss.NewStyle().Foreground(lipgloss.Color(searchAccentOrange)).Bold(true)
		focused.Text = lipgloss.NewStyle()
		focused.Placeholder = lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
		s.Focused = focused
		s.Cursor.Color = lipgloss.Color(searchAccentOrange)
		ti.SetStyles(s)
	}

	var apiPage int
	if results != nil {
		apiPage = 1
	}

	m := searchModel{
		results:   results,
		total:     total,
		width:     ss.width,
		mode:      modeBrowse,
		input:     ti,
		searchCfg: cfg,
		apiPage:   apiPage,
		styles:    styles,
		browseVP:  viewport.New(viewport.WithWidth(ss.width), viewport.WithHeight(1)), // height set on first WindowSizeMsg
		darkBg:    termenv.HasDarkBackground(),
	}
	m = m.refreshBrowseContent()
	return m
}

func (m searchModel) Init() tea.Cmd {
	if m.mode == modeSearch {
		return textinput.Blink
	}
	return nil
}

func (m searchModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:cyclop // bubbletea interface
	switch msg := msg.(type) {
	case searchResultsMsg:
		m.loading = false
		m.fetchingMore = false
		if msg.err != nil {
			m.searchErr = msg.err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.searchErr = ""
		m.results = msg.results
		m.total = msg.total
		m.counts = msg.counts
		m.apiPage = 1
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil

	case searchMoreResultsMsg:
		m.fetchingMore = false
		if msg.err != nil {
			m.searchErr = msg.err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.apiPage++
		if len(msg.results) > 0 {
			m.results = append(m.results, msg.results...)
		} else {
			// API returned no more results — cap total to what we have
			m.total = len(m.results)
		}
		m = m.refreshBrowseContent()
		return m, nil

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.input.SetWidth(max(msg.Width-6, 30))
		m.browseVP.SetWidth(msg.Width)
		m.browseVP.SetHeight(max(msg.Height-1, 1)) // reserve 1 line for footer
		if m.mode == modeDetail {
			m.detailVP.SetWidth(msg.Width)
			m.detailVP.SetHeight(max(msg.Height-2, 1))
		}
		m = m.refreshBrowseContent()
		return m, nil

	case tea.KeyPressMsg:
		switch m.mode {
		case modeSearch:
			return m.updateSearchMode(msg)
		case modeDetail:
			return m.updateDetailMode(msg)
		case modeBrowse:
			return m.updateBrowseMode(msg)
		}
	}
	return m, nil
}

func (m searchModel) updateSearchMode(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch {
	case key.Matches(msg, keys.Back):
		m.mode = modeBrowse
		m.input.Blur()
		m = m.refreshBrowseContent()
		return m, nil
	case key.Matches(msg, keys.Confirm):
		raw := strings.TrimSpace(m.input.Value())
		if raw == "" {
			return m, nil
		}
		parsed := search.ParseSearchInput(raw)
		if err := search.ValidateRepoFilters(parsed.Repos); err != nil {
			m.searchErr = err.Error()
			m = m.refreshBrowseContent()
			return m, nil
		}
		m.mode = modeBrowse
		m.input.Blur()
		m.loading = true
		m.searchErr = ""
		cfg := m.searchCfg
		cfg.Query = parsed.Query
		if cfg.Query == "" {
			cfg.Query = search.WildcardQuery
		}
		cfg.Author = parsed.Author
		cfg.Date = parsed.Date
		cfg.Branch = parsed.Branch
		cfg.Repos = parsed.Repos
		m.searchCfg = cfg
		m = m.refreshBrowseContent()
		return m, performSearch(cfg)
	}

	var cmd tea.Cmd
	m.input, cmd = m.input.Update(msg)
	return m, cmd
}

func (m searchModel) updateBrowseMode(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	// Type tab keys (1/2/3)
	switch msg.String() {
	case "1":
		m.filterType = typeFilterCheckpoints
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil
	case "2":
		m.filterType = typeFilterSessions
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil
	case "3":
		m.filterType = typeFilterCommits
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil
	case "0":
		m.filterType = typeFilterAll
		m.cursor = 0
		m.page = 0
		m.browseVP.GotoTop()
		m = m.refreshBrowseContent()
		return m, nil
	}

	pageLen := len(m.pageResults())
	switch {
	case key.Matches(msg, keys.Quit), key.Matches(msg, keys.Back), msg.String() == "h":
		return m, tea.Quit
	case key.Matches(msg, keys.Up):
		if m.cursor > 0 {
			m.cursor--
			m = m.refreshBrowseContent()
		}
	case key.Matches(msg, keys.Down):
		if m.cursor < pageLen-1 {
			m.cursor++
			m = m.refreshBrowseContent()
		}
	case key.Matches(msg, keys.Home):
		m.page = 0
		m.cursor = 0
		m = m.refreshBrowseContent()
		m.browseVP.GotoTop()
	case key.Matches(msg, keys.End):
		filtered := m.filteredResults()
		if len(filtered) > 0 {
			lastLoaded := len(filtered) - 1
			m.page = min(lastLoaded/resultsPerPage, m.totalPages()-1)
			if pageLen := len(m.pageResults()); pageLen > 0 {
				m.cursor = pageLen - 1
			}
			m = m.refreshBrowseContent()
			m.browseVP.GotoBottom()
		}
	case key.Matches(msg, keys.NextPage):
		if m.page < m.totalPages()-1 {
			m.page++
			m.cursor = 0
			m.browseVP.GotoTop()
			// Fetch next API page if we've scrolled past loaded results
			start := m.page * resultsPerPage
			if start >= len(m.filteredResults()) && !m.fetchingMore {
				m.fetchingMore = true
				m = m.refreshBrowseContent()
				return m, fetchMoreResults(m.searchCfg, m.apiPage+1)
			}
			m = m.refreshBrowseContent()
		}
	case key.Matches(msg, keys.PrevPage):
		if m.page > 0 {
			m.page--
			m.cursor = 0
			m.browseVP.GotoTop()
			m = m.refreshBrowseContent()
		}
	case key.Matches(msg, keys.Confirm):
		if r := m.selectedResult(); r != nil {
			m.mode = modeDetail
			content := m.renderDetailContent(*r, m.width, true)
			m.detailVP = viewport.New(viewport.WithWidth(m.width), viewport.WithHeight(max(m.height-2, 1)))
			m.detailVP.SetContent(content)
			return m, nil
		}
	case key.Matches(msg, keys.Search):
		m.mode = modeSearch
		m.input.Focus()
		return m, textinput.Blink
	default:
		// Forward unhandled keys (pgup/pgdn/ctrl+u/ctrl+d/g/G/etc.) to viewport for scrolling
		var cmd tea.Cmd
		m.browseVP, cmd = m.browseVP.Update(msg)
		return m, cmd
	}
	return m, nil
}

func (m searchModel) updateDetailMode(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch {
	case key.Matches(msg, keys.Quit):
		return m, tea.Quit
	case key.Matches(msg, keys.Back), msg.String() == "backspace":
		m.mode = modeBrowse
		return m, nil
	case key.Matches(msg, keys.Search):
		m.mode = modeSearch
		m.input.Focus()
		return m, textinput.Blink
	}
	var cmd tea.Cmd
	m.detailVP, cmd = m.detailVP.Update(msg)
	return m, cmd
}

func performSearch(cfg search.Config) tea.Cmd {
	return func() tea.Msg {
		resp, err := search.Search(context.Background(), cfg)
		if err != nil {
			return searchResultsMsg{err: err}
		}
		return searchResultsMsg{results: resp.Results, total: resp.Total, counts: resp.Counts}
	}
}

func fetchMoreResults(cfg search.Config, page int) tea.Cmd {
	return func() tea.Msg {
		cfg.Page = page
		resp, err := search.Search(context.Background(), cfg)
		if err != nil {
			return searchMoreResultsMsg{err: err}
		}
		return searchMoreResultsMsg{results: resp.Results}
	}
}

// ─── View ────────────────────────────────────────────────────────────────────

func (m searchModel) View() tea.View {
	v := tea.View{AltScreen: true}
	if m.width == 0 {
		return v
	}

	switch m.mode {
	case modeDetail:
		v.SetContent(m.viewDetailFull())
	case modeSearch:
		v.SetContent(m.viewSearchMode())
	case modeBrowse:
		v.SetContent(m.browseVP.View() + "\n" + m.viewHelp())
	}
	return v
}

func (m searchModel) viewSearchHeader(b *strings.Builder) {
	pad := " "
	b.WriteString("\n")
	b.WriteString(pad + m.styles.render(m.styles.sectionTitle, "SEARCH"))
	b.WriteString("\n\n")
}

func (m searchModel) viewSearchMode() string {
	var b strings.Builder
	m.viewSearchHeader(&b)
	b.WriteString(" " + m.input.View())
	b.WriteString("\n\n")
	if m.searchErr != "" {
		b.WriteString(" " + m.styles.render(m.styles.red, "Error: "+m.searchErr))
		b.WriteString("\n\n")
	}
	b.WriteString(" " + m.styles.render(m.styles.dim, "  Filters: author:<name>  date:<week|month>  branch:<name>  repo:<owner/name|*>"))
	b.WriteString("\n")
	b.WriteString(" " + m.styles.render(m.styles.dim, "  repo:* searches all accessible repos"))
	b.WriteString("\n\n")
	b.WriteString(m.viewHelp())
	return b.String()
}

// viewTypeTabs renders the type filter tabs with counts.
func (m searchModel) viewTypeTabs() string {
	cpCount, cmCount, ssCount := m.computeTypeCounts()
	allCount := cpCount + cmCount + ssCount

	renderTab := func(label string, filter typeFilter, count int, keyHint string) string {
		text := fmt.Sprintf("[%s] %s %d", keyHint, label, count)
		if m.filterType == filter {
			return m.styles.render(m.styles.tabActive, text)
		}
		return m.styles.render(m.styles.tabInactive, text)
	}

	tabs := []string{
		renderTab("All", typeFilterAll, allCount, "0"),
		renderTab("Checkpoints", typeFilterCheckpoints, cpCount, "1"),
		renderTab("Sessions", typeFilterSessions, ssCount, "2"),
		renderTab("Commits", typeFilterCommits, cmCount, "3"),
	}

	return strings.Join(tabs, "  ")
}

// renderBrowseContent builds the scrollable content for browse mode (everything except the footer).
func (m searchModel) renderBrowseContent() string {
	var b strings.Builder
	pad := " "

	m.viewSearchHeader(&b)

	query := m.input.Value()
	b.WriteString(pad + m.styles.render(m.styles.sectionTitle, "›") + " " + m.styles.render(m.styles.bold, query))
	b.WriteString("\n\n")

	// Loading / error / empty states
	if m.loading {
		b.WriteString(pad + m.styles.render(m.styles.dim, "Searching..."))
		return b.String()
	}
	if m.searchErr != "" {
		b.WriteString(pad + m.styles.render(m.styles.red, "Error: "+m.searchErr))
		return b.String()
	}
	if len(m.results) == 0 {
		b.WriteString(pad + m.styles.render(m.styles.dim, "No results found."))
		return b.String()
	}

	// Type tabs
	b.WriteString(pad + m.viewTypeTabs())
	b.WriteString("\n\n")

	// Section: RESULTS
	b.WriteString(pad + m.styles.render(m.styles.sectionTitle, "RESULTS"))
	b.WriteString("\n\n")

	// Table (current page only)
	filtered := m.filteredResults()
	if len(filtered) == 0 {
		b.WriteString(pad + m.styles.render(m.styles.dim, "No results for this type."))
		return b.String()
	}
	if m.fetchingMore && m.pageResults() == nil {
		b.WriteString(pad + m.styles.render(m.styles.dim, "Loading more results...") + "\n")
	} else {
		b.WriteString(m.viewTable())
	}
	b.WriteString("\n")

	// Detail card (no truncation — viewport handles overflow)
	if r := m.selectedResult(); r != nil {
		b.WriteString(m.viewDetailCard(*r))
	}

	return strings.TrimRight(b.String(), "\n")
}

// refreshBrowseContent rebuilds the browse viewport content from current state.
func (m searchModel) refreshBrowseContent() searchModel {
	m.browseVP.SetContent(m.renderBrowseContent())
	return m
}

func (m searchModel) viewTable() string {
	contentWidth := max(m.width-2, 0) // 1 char padding each side
	cols := computeColumns(contentWidth)
	pad := " "

	var b strings.Builder

	// Column headers
	hdr := fmt.Sprintf("%-*s %-*s %-*s %-*s %-*s %-*s %-*s",
		cols.typeCol, "Type",
		cols.age, "Age",
		cols.id, "ID",
		cols.branch, "Branch",
		cols.repo, "Repo",
		cols.prompt, "Title",
		cols.author, "Author",
	)
	b.WriteString(pad + m.styles.render(m.styles.dim, hdr) + "\n")

	// Header separator
	b.WriteString(pad + m.styles.render(m.styles.dim, strings.Repeat("─", contentWidth)) + "\n")

	// Rows
	for i, r := range m.pageResults() {
		row := m.viewRow(r, cols)
		if i == m.cursor && m.styles.colorEnabled {
			b.WriteString(pad + m.styles.selected.Render(row))
		} else {
			b.WriteString(pad + row)
		}
		b.WriteString("\n")
	}

	return b.String()
}

// typeLabel returns a short type badge for display in the table.
func typeLabel(resultType string) string {
	switch resultType {
	case search.TypeCheckpoint:
		return "CP"
	case search.TypeCommit:
		return "CM"
	case search.TypeSession:
		return "SS"
	default:
		return strings.ToUpper(resultType[:min(2, len(resultType))])
	}
}

func (m searchModel) viewRow(r search.Result, cols columnLayout) string {
	typeBadge := fmt.Sprintf("%-*s", cols.typeCol, typeLabel(r.Type))
	age := fmt.Sprintf("%-*s", cols.age, stringutil.TruncateRunes(formatSearchAge(r.ResultCreatedAt()), cols.age, ""))
	id := fmt.Sprintf("%-*s", cols.id, stringutil.TruncateRunes(formatResultID(r), cols.id-1, "…"))
	branch := fmt.Sprintf("%-*s", cols.branch, stringutil.TruncateRunes(r.ResultBranch(), cols.branch-1, "…"))
	repo := fmt.Sprintf("%-*s", cols.repo, stringutil.TruncateRunes(
		r.ResultOrg()+"/"+r.ResultRepo(), cols.repo-1, "…",
	))
	title := fmt.Sprintf("%-*s", cols.prompt, stringutil.TruncateRunes(
		stringutil.CollapseWhitespace(r.ResultTitle()), cols.prompt-1, "…",
	))
	author := fmt.Sprintf("%-*s", cols.author, stringutil.TruncateRunes(r.ResultAuthor(), cols.author-1, "…"))

	return fmt.Sprintf("%s %s %s %s %s %s %s", typeBadge, age, id, branch, repo, title, author)
}

// formatResultID returns a display-friendly ID for a result.
func formatResultID(r search.Result) string {
	if r.Type == search.TypeCommit && r.Commit != nil && len(r.Commit.CommitSHA) > 7 {
		return r.Commit.CommitSHA[:7]
	}
	return r.ResultID()
}

// renderDetailContent builds the text content for a result detail (no border/card chrome).
func (m searchModel) renderDetailContent(r search.Result, contentWidth int, showSections bool) string {
	switch r.Type {
	case search.TypeCheckpoint:
		return m.renderCheckpointDetail(r, contentWidth, showSections)
	case search.TypeCommit:
		return m.renderCommitDetail(r, contentWidth, showSections)
	case search.TypeSession:
		return m.renderSessionDetail(r, contentWidth, showSections)
	default:
		return m.renderCheckpointDetail(r, contentWidth, showSections)
	}
}

func (m searchModel) renderCheckpointDetail(r search.Result, contentWidth int, showSections bool) string {
	const labelWidth = 12
	valueWidth := contentWidth - labelWidth - 1
	if valueWidth < 20 {
		valueWidth = 0
	}

	var content strings.Builder

	content.WriteString(m.styles.render(m.styles.detailTitle, "Checkpoint Detail"))
	content.WriteString("\n")

	formatLabel := func(label string) string {
		return m.styles.render(m.styles.label, fmt.Sprintf("%-*s", labelWidth, label+":"))
	}

	writeField := func(label, value string) {
		content.WriteString(formatLabel(label) + " " + value + "\n")
	}

	writeWrappedField := func(label, value string) {
		if valueWidth == 0 || len(value) <= valueWidth {
			writeField(label, value)
			return
		}
		indent := strings.Repeat(" ", labelWidth+1)
		wrapped := wrapText(value, valueWidth)
		lines := strings.Split(wrapped, "\n")
		content.WriteString(formatLabel(label) + " " + lines[0] + "\n")
		for _, line := range lines[1:] {
			content.WriteString(indent + line + "\n")
		}
	}

	writeSection := func(title string) {
		if showSections {
			content.WriteString("\n" + m.styles.render(m.styles.detailTitle, title) + "\n")
		} else {
			content.WriteString("\n")
		}
	}

	cp := r.Checkpoint
	if cp == nil {
		return content.String()
	}

	// ── OVERVIEW ──
	writeSection("OVERVIEW")
	writeField("ID", cp.ID)
	writeWrappedField("Prompt", stringutil.CollapseWhitespace(cp.Prompt))
	matchType := r.Meta.MatchType
	if r.Meta.Score > 0 {
		matchType += " " + m.styles.render(m.styles.dim, fmt.Sprintf("(score: %.3f)", r.Meta.Score))
	}
	writeField("Match", matchType)

	// ── SOURCE ──
	writeSection("SOURCE")
	writeWrappedField("Commit", formatCommit(cp.CommitSHA, cp.CommitMessage))
	writeField("Branch", cp.Branch)
	writeField("Repo", cp.Org+"/"+cp.Repo)
	authorStr := cp.Author
	if cp.AuthorUsername != nil && *cp.AuthorUsername != "" {
		authorStr = *cp.AuthorUsername + " " + m.styles.render(m.styles.dim, "("+cp.Author+")")
	}
	writeField("Author", authorStr)
	createdStr := formatDetailCreatedAt(cp.CreatedAt, m.styles)
	writeField("Created", createdStr)

	// ── SNIPPET ──
	if r.Meta.Snippet != "" {
		writeSection("SNIPPET")
		switch {
		case showSections:
			content.WriteString(renderSnippetMarkdown(r.Meta.Snippet, contentWidth, m.darkBg) + "\n")
		case valueWidth > 0:
			content.WriteString(wrapText(r.Meta.Snippet, contentWidth) + "\n")
		default:
			content.WriteString(r.Meta.Snippet + "\n")
		}
	}

	// ── FILES ──
	if len(cp.FilesTouched) > 0 {
		content.WriteString("\n")
		if showSections {
			content.WriteString(m.styles.render(m.styles.detailTitle, "FILES") + "\n")
		} else {
			content.WriteString(m.styles.render(m.styles.label, "Files:") + "\n")
		}
		for _, f := range cp.FilesTouched {
			content.WriteString("  " + f + "\n")
		}
	}

	return strings.TrimRight(content.String(), "\n")
}

