func TestSearch_SuccessWithMultipleTypes(t *testing.T) {
	t.Parallel()

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.Write([]byte(`{
			"results": [
				{
					"type": "checkpoint",
					"data": {"id": "cp1", "prompt": "fix bug", "branch": "main", "org": "o", "repo": "r", "author": "alice", "createdAt": "2026-01-13T12:00:00Z", "filesTouched": []},
					"searchMeta": {"matchType": "keyword", "score": 0.5}
				},
				{
					"type": "commit",
					"data": {"id": "cm1", "commitSha": "abc1234567890", "commitMessage": "fix: auth bug", "commitSubject": "fix: auth bug", "branch": "main", "org": "o", "repo": "r", "author": "bob", "createdAt": "2026-01-14T12:00:00Z", "additions": 10, "deletions": 5, "filesChanged": 3},
					"searchMeta": {"matchType": "semantic", "score": 0.3}
				},
				{
					"type": "session",
					"data": {"sessionId": "ss1", "displayName": "Debug auth", "org": "o", "repo": "r", "createdAt": "2026-01-15T12:00:00Z", "stepCount": 5},
					"searchMeta": {"matchType": "both", "score": 0.4}
				}
			],
			"total": 3,
			"page": 1,
			"counts": {"repos": 0, "checkpoints": 1, "commits": 1, "prs": 0, "sessions": 1}
		}`))
	}))
	defer srv.Close()

	resp, err := Search(context.Background(), Config{
		ServiceURL:  srv.URL,
		GitHubToken: "tok",
		Owner:       "o",
		Repo:        "r",
		Query:       "auth",
