	// Commit
	if resp.Results[1].Commit == nil {
		t.Fatal("result[1] commit is nil")
	}
	if resp.Results[1].Commit.CommitSHA != "abc1234567890" {
		t.Errorf("commit SHA = %q", resp.Results[1].Commit.CommitSHA)
	}
	if resp.Results[1].Commit.Additions != 10 {
