			"results": [
				{
					"type": "checkpoint",
					"data": {
						"id": "abc123def456",
						"branch": "main",
						"prompt": "add auth middleware",
						"author": "alice",
						"createdAt": "2026-01-13T12:00:00Z",
						"org": "",
						"repo": "",
						"filesTouched": []
					},
					"searchMeta": {
						"score": 0.042,
						"matchType": "both"
					}
				}
			],
			"total": 1,
			"page": 1
		}`))
