	if resp.Counts == nil {
		t.Fatal("counts is nil")
	}
	if resp.Counts.Checkpoints != 1 || resp.Counts.Commits != 1 || resp.Counts.Sessions != 1 {
		t.Errorf("counts = %+v", resp.Counts)
	}
}

