		t.Fatal(err)
	}

	if capturedReq.URL.Path != "/search/v1/search" {
		t.Errorf("path = %s, want /search/v1/search", capturedReq.URL.Path)
	}
	if capturedReq.URL.Query().Get("q") != "find bugs" {
