	t.Parallel()

	p := ParseSearchInput("repo:*")
	if p.Query != "" {
		t.Errorf("query = %q, want empty", p.Query)
	}
	if got := p.Repos; len(got) != 1 || got[0] != AllReposFilter {
		t.Errorf("repos = %v, want %v", got, []string{AllReposFilter})
	}
}

