	t.Parallel()
	p := ParseSearchInput("author:bob")
	if p.Query != "" {
		t.Errorf("query = %q, want empty", p.Query)
	}
	if p.Author != "bob" {
		t.Errorf("author = %q, want 'bob'", p.Author)
